(window.YSKAR_TEXTE=window.YSKAR_TEXTE||{}).pl={"nav.skip":"Przejdź do treści","nav.main":"Główna nawigacja","nav.menu":"Menu","nav.close":"Zamknij","nav.lang":"Język","nav.tick":"Blok","nav.tick.title":"Najnowszy blok. Otwiera stronę sieci na żywo.","cta.join":"Dołącz","nav.g.part":"Dołącz","nav.g.know":"Zrozum","nav.g.join":"Bądź z nami","nav.start":"Od czego zacząć","nav.start.d":"Pięć dróg wejścia, każda z pierwszym krokiem","nav.mine":"Mining","nav.mine.d":"Znajduj bloki telefonem, komputerem albo kartą graficzną","nav.wallet":"Portfel","nav.wallet.d":"Dwanaście słów, które masz tylko Ty","nav.node":"Uruchom węzeł","nav.node.d":"Sprawdzaj każdy blok samodzielnie","nav.ysr":"YSR","nav.ysr.d":"21 milionów, każdy wykopany","nav.chain":"Łańcuch","nav.chain.d":"Własny blockchain i to, jak sam dowodzi swojej poprawności","nav.network":"Sieć na żywo","nav.network.d":"Co łańcuch robi w tej chwili","nav.explorer":"Explorer","nav.explorer.d":"Każdy blok, każdy przelew, każdy adres","nav.community":"Społeczność","nav.community.d":"Tu projekt rozmawia i decyduje","nav.build":"Twórz","nav.build.d":"Otwarty kod, publiczne API, propozycje","nav.story":"Historia i kolejne kroki","nav.story.d":"Od bloku 0 do dziś i co będzie dalej","foot.claim":"Uczciwy od bloku 0.","foot.sub":"YSKAR to projekt społeczności. Nie stoi za nim żadna firma i nikomu nie trzeba wierzyć na słowo: każdy blok można sprawdzić.","foot.nav":"Wszystkie strony","foot.whitepaper":"Whitepaper","foot.find":"Gdzie znaleźć YSKAR","foot.imprint":"Nota prawna","foot.privacy":"Prywatność","foot.license":"Open source na licencji MIT","title.home":"Uczciwy od bloku 0","title.start":"Od czego zacząć","title.mine":"Mining","title.wallet":"YSKAR Wallet","title.node":"Uruchom węzeł","title.ysr":"YSR, moneta","title.chain":"Łańcuch","title.network":"Sieć na żywo","title.explorer":"Explorer","title.build":"Twórz na YSKAR","title.community":"Społeczność","title.story":"Historia i kolejne kroki","ui.copied":"Skopiowano","ui.copy":"Kopiuj","ui.sample":"Ekran pokazuje przykładowe dane.","dawn.h":"Tu jest jeszcze wcześnie.","dawn.p":"Dzień <span data-live='day'></span>. Pierwsze światło dopiero wschodzi nad tą siecią. Kształtują ją ludzie, którzy są tu teraz.","dawn.cta2":"Przeczytaj dotychczasową historię","dawn.alt":"Ten sam fiord o pierwszym świetle: blade niebo nad ośnieżonymi górami i nieruchomą wodą.","nav.guides":"Poradniki","nav.guides.d":"Wszystkie sposoby udziału, krok po kroku","nav.protocol":"Protokół","nav.protocol.d":"Moneta, łańcuch i portfele, bajt po bajcie","nav.paper.d":"System taki, jaki został zaimplementowany","title.guides":"Poradniki","title.protocol":"Protokół","title.paper":"Whitepaper","title.imprint":"Nota prawna","title.privacy":"Prywatność","doc.toc":"Na tej stronie","foot.live":"Liczby na tych stronach są odczytywane na żywo z publicznego API YSKAR.","foot.stale":"Publiczne API YSKAR w tej chwili nie odpowiada. Te strony pokazują łańcuch według stanu z {date} (blok {h}) i same nadrobią zaległości.","title.notfound":"Nie znaleziono strony","nf.h":"Ta strona nie istnieje.","nf.p":"Być może link zawiera literówkę albo strona została przeniesiona. Sam łańcuch jest dokładnie tam, gdzie był.","nf.home":"Do strony głównej","nf.explorer":"Wyszukaj coś w explorerze","home.hero.h1":"<span class=\"ln\"><span>Proof,</span></span> <span class=\"ln\"><span>not promise.</span></span>","home.hero.lead":"YSKAR to waluta z własnym blockchainem. Niczego nie rozdano z góry: każdy YSR jest wykopany, a każdy blok może sprawdzić każdy. Uczciwy od bloku 0.","home.hero.cta2":"Zobacz dotychczasowy łańcuch","home.hero.live":"Dzień {d} · blok {h} · świateł na brzegu: {n}, po jednym dla każdego węzła, który się zgłosił","home.hero.alt":"Ciemny fiord między ośnieżonymi górami pod rozgwieżdżonym niebem. Nad nim poruszają się wstęgi niebieskiego światła, a na dalekim brzegu jarzą się małe ciepłe światła.","home.m1":"Nie zaczęło się od obietnicy. Zaczęło się od bloku.","home.m2":"Niczego nie wykopano z góry. Niczego nie rozdano. Około 1,07 mln YSR z pierwszych dni spalono, żeby wyrównać przewagę na starcie.","home.m3":"Od tamtej pory nowy YSR przychodzi na świat tylko w jeden sposób: maszyna wykonuje pracę, a każdy może to sprawdzić.","walk.start.h":"<span data-live='day'></span> dni, blok po bloku.","walk.start.p":"Każde światło to prawdziwy blok, a odstęp między dwoma światłami to czas, który je dzieli. Przewijaj, żeby podróżować wzdłuż łańcucha. Dotknij światła, żeby otworzyć jego blok.","walk.c0.h":"Zaczyna się od jednego bloku.","walk.c0.p":"Jego jedyna wiadomość to „proof, not promise”. Jego nagroda w wysokości 875 YSR trafiła na adres, z którego nikt nie może niczego wydać.","walk.c1.h":"Dzień pierwszy: 46 bloków.","walk.c1.p":"Pierwszy blok po bloku 0 pojawił się o 18:03 UTC. Do północy było ich 46: łańcuch znalazł swój rytm.","walk.c3.h":"Przewaga ze startu zostaje spalona.","walk.c3.p":"1 066 101 YSR z pierwszych dni trafia na adres, z którego nikt nie może niczego wydać, żeby wyrównać przewagę na starcie. Wszystko jest w tym bloku.","walk.c4.h":"Społeczność głosuje.","walk.c4.p":"Wersja 6 jest ustalana jawnie: konta wspólne, blokady czasowe, płatności do tysiąca odbiorców naraz. Trzy aktualizacje zasad działały już wcześniej.","walk.c5.h":"Jesteś tutaj.","walk.c5.p":"Do następnego bloku zostało około dziesięciu minut.","walk.c6.h":"Następnie: włącza się wersja 6.","walk.c6.p":"Pozostało bloków: <span data-live='v6Left'></span>. Każdy węzeł zna wysokość z góry, więc nic nie zmienia się z zaskoczenia.","walk.c6.h.past":"Wersja 6 jest aktywna.","walk.c6.p.past":"Od bloku 10 000 łańcuch zna konta wspólne, blokady czasowe i płatności zbiorcze.","walk.c7.h":"Potem kończy się pierwsza era.","walk.c7.p":"Do bloku 12 000 każdy blok tworzy 875 YSR, potem 437,5. Połowa wszystkich YSR, jakie kiedykolwiek powstaną, pochodzi z tej pierwszej ery.","walk.c7.h.past":"Pierwsza era dobiegła końca.","walk.c7.p.past":"Od bloku 12 000 każdy blok tworzy 437,5 YSR. Nagroda zmniejsza się o połowę co kolejne 12 000 bloków.","walk.open":"Otwórz ten blok","walk.k.block":"Blok {h} · {d}","walk.k.future":"Blok {h} · jeszcze przed nami","home.walk.now":"Blok {h} · dzień {d}","walk.hud.block":"Blok {h}","walk.hud.ahead":"Blok {h}","walk.hud.planned":"jeszcze przed nami · zapisane w kodzie","walk.hud.day":"dzień {n}","walk.tip.block":"Blok {h}","walk.tip.approx":"Szczegóły wczytują się w explorerze","walk.tip.solo":"Znaleziony przez pojedynczego minera","walk.tip.pool":"Znaleziony przez pool","walk.tip.tx":"zawierał przelewy","walk.legend.block":"blok","walk.legend.tx":"blok, który zawierał przelewy","walk.canvas":"Łańcuch narysowany jako wstęga świateł, po jednym świetle dla każdego bloku od bloku 0.","home.proof.h":"Nie wierz nam na słowo.","home.proof.p":"Każdy blok niesie własny dowód. Twoje urządzenie może go sprawdzić od razu: bez serwera, bez konta, sama arytmetyka.","prove.btn.genesis":"Sprawdź blok 0 na tym urządzeniu","prove.btn.tip":"Sprawdź najnowszy blok","prove.label":"Hash nagłówka bloku","prove.ok":"Poprawny. Blok {h} został sprawdzony na tym urządzeniu w {ms} ms.","prove.bad":"Niepoprawny: blok {h} nie spełnia swojego celu.","prove.open":"Otwórz blok {h} w explorerze","prove.note":"Co właśnie zrobiło Twoje urządzenie: dwukrotnie przepuściło 136 bajtów nagłówka bloku przez SHA-256. Wynik musi być mniejszy niż cel, który sieć wyznaczyła dla tego bloku. Zera na początku pokazują, jak bardzo jest mały.","home.ways.h":"Trzy drogi wejścia.","home.ways.p":"Znak YSKAR to trzy wstęgi, które się spotykają. Taka jest też sieć: ludzie, którzy kopią, ludzie, którzy przechowują i wysyłają, oraz ludzie, którzy utrzymują węzeł.","way.mine.h":"Użycz jej swojej maszyny.","way.mine.p":"Telefon, komputer albo karta graficzna mogą znajdować bloki. Samodzielnie albo w poolu, który płaci Ci w samym bloku i nigdy nie przechowuje Twoich monet.","way.mine.cta":"Jak działa mining","way.mine.alt":"Laptop na drewnianym biurku nocą, z uruchomionym YSKAR Node Core; za nim okno z widokiem na ciemny fiord.","way.wallet.h":"Dwanaście słów. Tylko Twoich.","way.wallet.p":"Twój portfel znajduje się na Twoim własnym urządzeniu. Nikt inny nie ma Twoich kluczy, także ludzie, którzy budują YSKAR.","way.wallet.cta":"Pobierz portfel","way.wallet.alt":"Telefon z otwartym YSKAR Wallet leży na ciemnym drewnianym biurku obok notesu z dwunastoma odręcznymi linijkami, długopisu i filiżanki herbaty.","way.node.h":"Zostaw zapalone światło.","way.node.p":"Węzeł sam sprawdza każdy blok, od bloku 0. Każdy kolejny sprawia, że sieć trudniej nagiąć. Wystarczy mały komputer na parapecie.","way.node.cta":"Uruchom węzeł","way.node.alt":"Mały komputer z jedną cyjanową diodą na drewnianym parapecie; za oknem fiord nocą i kilka świateł na dalekim brzegu.","home.ways.more":"Albo buduj na nim. Kod jest otwarty, API jest publiczne, a propozycje omawia się tam, gdzie każdy może je przeczytać.","home.ways.more.cta":"Dla deweloperów","home.early.say":"Dzień {d}. Węzłów: {n}. Minerów: {m}. Pooli: {p}. Przelewów: {x}. Bez notowań. Bez ceny. Tak wygląda początek.","home.early.note":"Węzły i minerzy według tego, jak sami się zgłaszają. Wszystkie liczby pochodzą z publicznego API.","home.early.p":"Mała sieć, która ma <span data-live='day'></span> dni. YSR nie jest nigdzie notowany i nie ma ceny; notowania są w przygotowaniu, bez daty i bez nazw. Dziś istnieje łańcuch, który działa, oprogramowanie, które możesz uruchomić, i miejsce dla tych, którzy pojawiają się teraz.","home.era.h":"Era <span data-live='era'></span>","home.era.p":"W tej erze każdy blok tworzy <span data-live='rewardNow'></span> YSR. W bloku <span data-live='halvingHeight'></span> nagroda zmniejsza się o połowę, a potem znowu co 12 000 bloków. Połowa wszystkich YSR, jakie kiedykolwiek powstaną, pochodzi z pierwszych 12 000 bloków. Harmonogram jest zapisany w kodzie; nikt nie może go przesunąć.","home.era.now":"Blok <span data-live='height'></span>","home.era.left":"Pozostało bloków: <span data-live='halvingLeft'></span>","home.era.cta":"Cały harmonogram","home.people.h":"Żadnej firmy. Tylko ludzie.","home.people.p":"YSKAR to projekt społeczności i należy do ludzi, którzy z niego korzystają. Kopią, utrzymują węzły, testują wydania i jawnie decydują o zmianach: wersję 6 poddano głosowaniu społeczności.","home.people.cta":"Poznaj społeczność","home.people.cta2":"Otwórz YSKAR Lab","home.people.alt":"Około piętnastu osób widzianych od tyłu na zaśnieżonym brzegu o niebieskiej godzinie; każda trzyma małą latarnię i patrzy na fiord.","start.h1":"Wybierz swoją drogę wejścia.","start.lead":"Udział nic nie kosztuje. Zacznij od tego, co Ci pasuje; te same dwanaście słów otworzy później każde drzwi.","start.1.h":"Chcę przechowywać i wysyłać YSR","start.1.p":"Zainstaluj portfel na Androida, zapisz dwanaście słów na papierze, pokaż swój adres. Tyle wystarczy, żeby odbierać.","start.1.do":"Do portfela","start.2.h":"Chcę kopać","start.2.p":"Zacznij od urządzenia, które już masz: Node Core na komputerze, aplikacja na Androida w telefonie, wiersz poleceń na koparce.","start.2.do":"Do miningu","start.3.h":"Chcę sam sprawdzać łańcuch","start.3.p":"Uruchom węzeł. Weryfikuje każdy blok od bloku 0 i staje się kolejnym światłem na brzegu.","start.3.do":"Uruchom węzeł","start.4.h":"Chcę tworzyć albo pomagać","start.4.p":"Przeczytaj kod, odpytaj publiczne API, przetestuj wydanie, zgłoś propozycję w YSKAR Lab.","start.4.do":"Dla deweloperów","start.5.h":"Na razie chcę tylko popatrzeć","start.5.p":"Śledź łańcuch na żywo, otwórz dowolny blok w explorerze, czytaj rozmowy na kanale.","start.5.do":"Sieć na żywo","start.safe.h":"Trzy rzeczy na początek","start.alt.fjord":"Ciemny fiord pod rozgwieżdżonym niebem.","mine.h1":"Użycz jej swojej maszyny.","mine.lead":"Nowe YSR powstają z miningu i z niczego innego. Wziąć udział może telefon, komputer albo karta graficzna, samodzielnie lub w poolu.","mine.cta":"Wybierz swoją konfigurację","mine.cta2":"Wypróbuj od razu tutaj","mine.try.h":"Mining to zgadywanie, bardzo szybkie.","mine.try.p":"Naciśnij start, a to urządzenie na chwilę dołączy. Bierze najnowszy blok i szuka liczby, dzięki której jego hash zaczyna się od wystarczającej liczby zer: to samo poszukiwanie, które prowadzi każdy miner, tylko przy ćwiczebnej trudności.","mine.try.go":"Zacznij zgadywać","mine.try.stop":"Stop","mine.try.again":"Jeszcze raz","mine.try.tries":"Próby","mine.try.speed":"Tempo","mine.try.idle":"Na razie nic. Każda iskra to seria prób.","mine.try.found":"Znaleziono. Liczba prób: {n}.","mine.try.none":"Liczba prób: {n}, bez szczęścia. To też jest mining. Spróbuj jeszcze raz.","mine.try.real":"To było ćwiczenie. Prawdziwa sieć jest {x} razy trudniejsza: przy {r} samo to urządzenie szukałoby jednego prawdziwego bloku mniej więcej {t}. Dlatego minerzy łączą się w poole.","mine.try.canvas":"Iskry dla każdej serii prób; jasny błysk, gdy zostanie znaleziona poprawna liczba.","mine.setup.h":"Wybierz swoją konfigurację","mine.calc.h":"Co mogłaby znaleźć Twoja maszyna?","mine.pools.h":"Poole na żywo","wal.h1":"Dwanaście słów. Tylko Twoich.","wal.lead":"YSKAR Wallet to aplikacja na Androida dla YSR: wysyłaj, odbieraj, podpisuj. Twój klucz powstaje w Twoim telefonie i tam zostaje.","wal.cta2":"Instalacja w czterech krokach","wal.say":"Kto ma dwanaście słów, ten ma środki. Zapisz je na papierze. Nikt z YSKAR nigdy Cię o nie nie poprosi.","node.h1":"Zostaw zapalone światło.","node.lead":"Pełny węzeł sam sprawdza każdy blok, od bloku 0, i przekazuje go dalej. Nikogo nie pyta, co jest prawdą. Każdy węzeł, który to robi, sprawia, że sieć trudniej nagiąć.","node.cta":"Pobierz Node Core","node.cta2":"Z wiersza poleceń","node.say":"Każde światło na tym brzegu to węzeł, który się zgłosił. W tej chwili jest ich {n}. Twój miałby numer {k}.","node.core.h":"Node Core: węzeł, portfel i miner w jednym oknie.","node.core.p":"Zainstaluj go, a Twój komputer sam zweryfikuje łańcuch. Node Core przechowuje też Twój portfel, kopie procesorem lub kartą graficzną, może prowadzić pool i podpisuje wiadomości. Wersja 1.1.0 dla Windows 10 i 11 oraz dla 64-bitowego Linuksa.","node.dl.win":"Instalator dla Windows","node.dl.deb":"Pakiet dla Linuksa (.deb)","node.dl.app":"AppImage dla Linuksa","node.dl.get":"Pobierz","node.dl.all":"Wszystkie pliki i sumy kontrolne","node.dl.rel":"Wydanie na GitHubie","node.why.h":"Co zmienia jeden węzeł więcej","node.w1.p":"Twój węzeł przelicza pracę, podpisy i każde saldo, zaczynając od bloku 0. Blok, który łamie regułę, zostaje odrzucony, bez względu na to, kto go przysłał.","node.w2.h":"Niesie sieć","node.w2.p":"Każdy węzeł przekazuje bloki i przelewy innym. Im więcej ich jest i w im większej liczbie miejsc, tym mniej sieć zależy od pojedynczej maszyny.","node.w3.h":"Potrzebuje niewiele","node.w3.p":"Z wiersza poleceń węzeł działa na Linuksie, Windows i macOS, nawet na Raspberry Pi. Node Core, aplikacja na komputer, działa na Windows i 64-bitowym Linuksie.","coin.h1":"21 milionów. Każdy wykopany.","coin.lead":"YSR to moneta łańcucha YSKAR. Nigdy nie będzie ich więcej niż 21 000 000. Niczego nie wykopano wcześniej ani nie przydzielono: nowy YSR powstaje tylko z jednego powodu, bo znaleziono blok.","coin.alt":"Moneta YSR: gruby dysk z niebieskiego szkła z podniesionym rantem i wypukłym znakiem YSKAR.","coin.alt.flat":"Moneta YSR: ciemny dysk z niebieskim pierścieniem i znakiem YSKAR.","coin.bar.mined":"wykopane do tej pory","coin.bar.burned":"z tego spalone lub niemożliwe do wydania","coin.bar.open":"jeszcze do wykopania","coin.eras.h":"Nagroda zmniejsza się o połowę co 12 000 bloków.","coin.eras.p":"Każdy słupek to jedna era i pokazuje, ile YSR w niej powstaje. Sama pierwsza era tworzy połowę wszystkiego. Ostatni nowy YSR pojawi się w bloku 443 999; potem minerzy zarabiają już tylko na opłatach.","coin.eras.era":"Era {n}","coin.eras.now":"teraz","coin.eras.rest":"Wartości w YSR. 9+ oznacza wszystkie późniejsze ery łącznie.","coin.burn.h":"Przewagę ze startu spalono.","coin.burn.cta":"Zobacz to w bloku 3974","chain.h1":"Własny łańcuch.","chain.lead":"YSKAR nie działa na cudzej sieci. Ma własne bloki, własną sieć peer-to-peer i własne zasady, a każdy swój blok potwierdza pracą, którą każdy może sprawdzić.","chain.how.h":"Jeden blok, trzy kroki.","chain.why.h":"Dlaczego własny łańcuch ma znaczenie","chain.y1.h":"Jego zasady są jego własne","chain.y1.p":"O opłatach, czasach bloków i aktualizacjach decydują tutaj ludzie, którzy utrzymują YSKAR, a nie czyjaś inna sieć.","chain.y2.h":"Niczego nie trzeba brać na wiarę","chain.y2.p":"Każdy blok aż do bloku 0 może przeliczyć każdy, otwartym oprogramowaniem, na zwykłym komputerze.","chain.y3.h":"Zmiany przychodzą jawnie","chain.y3.p":"Zmiana zasad jest zapisywana w kodzie razem z blokiem, od którego zaczyna obowiązywać. Każdy węzeł zna ją z góry. Wersję 6 poddano głosowaniu społeczności.","chain.deep.h":"Dla ciekawych: jak to działa w szczegółach","chain.deep.p":"Od tego miejsca strona robi się techniczna. Wszystko poniżej pochodzi z kodu konsensusu i z samego łańcucha.","netp.lead":"Co łańcuch robi w tej chwili, odczytane z publicznego API. Niczego tu nie szacuje się ręcznie.","bld.h1":"Buduj na nim.","bld.lead":"Cały YSKAR jest otwarty: węzeł, portfele, minery, explorer i ta strona, na licencji MIT. Publiczne API odpowiada bez klucza.","bld.cta":"Wypróbuj API","bld.cta2":"Kod na GitHubie","bld.1.h":"Przeczytaj wszystko","bld.1.p":"Protokół jest opisany, kod konsensusu jest na tyle krótki, że da się go przeczytać, a każda liczba na tej stronie pochodzi z tego kodu albo z łańcucha.","bld.2.h":"Zapytaj łańcuch","bld.2.p":"Bloki, przelewy, adresy, opłaty, poole i podaż przez zwykłe HTTP. Bez klucza, bez rejestracji, dostępne dla każdej strony.","bld.3.h":"Zmień go","bld.3.p":"Propozycje przechodzą przez YSKAR Lab, publicznie, od pierwszego pomysłu do wydania. Logujesz się swoim portfelem.","comm.h1":"Żadnej firmy. Tylko ludzie.","comm.lead":"YSKAR to projekt społeczności i należy do ludzi, którzy z niego korzystają. To tutaj rozmawiają, testują i decydują.","comm.ch.h":"Gdzie wszystkich znaleźć","comm.do.h":"Co możesz zrobić. Nic z tego nie wymaga pozwolenia.","comm.lab.h":"Jak propozycja staje się wydaniem","comm.safe.h":"Dbaj o bezpieczeństwo","comm.ann":"Bitcointalk","story.h1":"Kroki, nie terminy.","story.lead":"Skąd pochodzi YSKAR, co działa dziś i co będzie dalej. Nikt tu nie obiecuje terminu: zmiany wchodzą w życie w określonym bloku, a nie w dniu z kalendarza.","story.why.h":"Po co istnieje YSKAR","story.why.say":"Celem jest waluta, której ludzie mogą używać na co dzień. Najpierw solidne fundamenty. Krótki zryw rozgłosu nie jest planem.","story.why.p":"YSKAR należy do ludzi, którzy z niego korzystają. Twoje YSR leżą pod adresem, który otwiera tylko Twoje dwanaście słów. Nikomu nie trzeba ufać: każdy blok aż do bloku 0 może sprawdzić każdy. Nowe YSR powstają z miningu, nigdy z obietnicy.","story.run.h":"Działa dzisiaj","story.fix.h":"Ustalone wysokością bloku","story.plan.h":"Planowane, bez terminu","story.walk":"Przejdź wzdłuż łańcucha od bloku 0","coin.field.alt":"Pole świateł dla wszystkich 21 milionów YSR: już wykopane świecą, spalone żarzą się jak węgle, reszta jest ciemna.","coin.field.burned":"spalone","coin.f0.h":"21 000 000. Nigdy więcej.","coin.f0.p":"Każde światło oznacza <span data-field-unit></span> YSR, w kolejności, w jakiej powstają. To wszystko, co kiedykolwiek będzie istnieć.","coin.f1.p":"Tyle istnieje dzisiaj, czyli <span data-live='mintedPct'></span> całości. Każdy z nich pochodzi z bloku, który ktoś znalazł.","coin.f2.p":"Około 1,07 mln YSR z pierwszych dni spalono, żeby wyrównać przewagę na starcie. Trafiły na adres, z którego nikt nie może niczego wydać, i przepadły na dobre.","coin.f3.h":"Połowa wszystkiego powstaje najpierw.","coin.f3.p":"Pierwsze 12 000 bloków tworzy 10,5 mln YSR: połowę wszystkiego, co kiedykolwiek powstanie. Łańcuch jest na bloku <span data-live='height'></span>.","coin.f4.h":"Potem nagroda maleje o połowę, raz za razem.","coin.f4.p":"Co 12 000 bloków nagroda jest zmniejszana o połowę. Ostatni nowy YSR pojawi się w bloku 443 999. Potem minerzy zarabiają już tylko na opłatach.","coin.noprice.say":"YSR nie ma dziś ceny. Nie jest nigdzie notowany. Ma za to łańcuch, który każdy może sprawdzić.","wal.phone.alt":"Telefon pokazujący prawdziwe ekrany YSKAR Wallet, jeden po drugim.","wal.s1.h":"Twoje saldo i nic, co by je zasłaniało.","wal.s3.h":"Jedna historia dla wszystkiego.","wal.s3.p":"Płatności, nagrody za bloki i udziały w poolu pojawiają się w jednym miejscu. Kwoty są dokładne do ósmego miejsca po przecinku.","wal.s5.h":"Nazwy dla adresów.","wal.s5.p":"Zapisz adres pod nazwą tylko raz. Od tej pory portfel pokazuje tę nazwę: w Twoich płatnościach, przy wysyłaniu i przy sprawdzaniu. Kontakty zostają na Twoim urządzeniu.","pay.alt":"Wiele małych świateł migocze, zbiera się w jeden jasny punkt, który staje się blokiem, a z bloku biegną promienie do każdego adresu, któremu płaci.","pay.0.h":"Wszyscy zgadują jednocześnie.","pay.0.p":"W tej chwili cała sieć pracuje z mocą około <span data-live='hashrate'></span>: miliardy liczb na sekundę, a wszystkie polują na ten sam blok.","pay.1.h":"Jedna liczba pasuje.","pay.1.p":"Mniej więcej co dziesięć minut jakaś maszyna znajduje liczbę, która pasuje. To nowy blok, a poszukiwanie zaczyna się od nowa.","pay.2.h":"Blok płaci wszystkim, którzy pomogli.","pay.2.p":"W poolu nagroda jest dzielona według pracy, jaką wykonał każdy miner, i wypłacana w samym bloku. Liczba adresów, którym zapłacił naraz najnowszy blok poola: <span id='pay-n'></span>.","pay.3.h":"Bez konta. Bez progu wypłaty. Bez powierzania środków.","calcx.a":"Moja maszyna osiąga","calcx.b":"i kopię","poolsx.last":"z najnowszych bloków","poolsx.fee":"opłata","poolsx.seats":"zajętych miejsc","poolsx.rate":"zgłoszono","shore.on":"Zapal jeszcze jedno","shore.off":"Zgaś je z powrotem","shore.note.on":"Numer {k} świeci tylko na Twoim ekranie. Zacznie się liczyć, gdy Twój węzeł będzie działał.","node.check.h":"Od bloku 0 do dziś, bez pytania kogokolwiek.","comm.vote.say":"25 października 2026 r. społeczność zagłosowała, kiedy zaczyna się wersja 6. Wybrała blok 10 000.","comm.vote.cta":"Co wnosi wersja 6","log.k":"Każdy blok do","log.cap":"Każdy wiersz to jeden dzień od 9 września 2026 r. (UTC), każda kreska to jeden blok o swojej porze dnia. Ciepłe kreski zawierały przelewy. Dotknij kreski, żeby otworzyć blok.","log.cap.n":"Każdy wiersz obejmuje {d} dni od 9 września 2026 r. (UTC), każda kreska to jeden blok. Ciepłe kreski zawierały przelewy. Dotknij kreski, żeby otworzyć blok.","log.alt":"Dziennik łańcucha: każdy blok od bloku 0 jako kreska, jeden wiersz na dzień.","comm.say":"Dzień {d}. Węzłów, które strzegą łańcucha: {n}. Minerów, którzy go przedłużają: {m}. Pooli, które dzielą się pracą: {p}. Nikt ich nie wyznaczył. Przyszli sami.","road.start.k":"25 paź 2026","road.start":"Głosowanie","road.end.k":"Blok 10 000","road.end":"Zaczyna się wersja 6","road.now":"Blok {h} · teraz","road.left":"Pozostało bloków: {n}. W obecnym tempie to {eta}.","road.done":"Wersja 6 jest aktywna od bloku 10 000.","road.need":"Przed tym blokiem węzły potrzebują aktualnego wydania.","road.need.done":"Węzły ze starszym wydaniem nie podążają już za łańcuchem.","coin.turn":"Odwróć ją","coin.turn.back":"Odwróć z powrotem","coin.back.k":"Blok 0","coin.back.d":"9 września 2026","netp.say":"Blok {h}, znaleziony {a}. Nad następnym pracuje {r}. Obserwujących węzłów: {n}.","start.jump":"Pięć dróg","start.guides":"Każda droga wyjaśniona krok po kroku","story.road.h":"Łańcuch do tej pory i to, co już ustalono","story.road.p":"Siedem znaczników wzdłuż łańcucha. Te za nami mają datę. Te przed nami mają tylko numer bloku, bo kod nie zna niczego więcej.","story.road.live":"Zobacz najnowsze bloki","miles.left":"pozostało bloków: {n}","forge.hash":"SHA-256, zastosowany dwukrotnie","forge.target":"nie może przekroczyć celu","forge.ok":"Poprawny: przeliczony na tym urządzeniu.","forge.nodes":"{n} zgłoszonych węzłów","forge.nodes.few":"{n} zgłoszone węzły","forge.nodes.1":"{n} zgłoszony węzeł","forge.paid":"{r} na {n} adresów","forge.paid.few":"{r} na {n} adresy","forge.paid.1":"{r} na {n} adres","forge.before":"Bloków przed nim: {n}, w odstępach, w jakich je znaleziono: {m} min","forge.alt":"136 bajtów nagłówka najnowszego bloku. Nonce zmienia się, aż hash spadnie poniżej celu; wtedy węzły go sprawdzają, a blok zajmuje miejsce na końcu łańcucha i wypłaca swoją nagrodę.","term.note.live":"Odpowiedź publicznego API z {d}.","term.note.snap":"Odpowiedź z {d}. API w tej chwili nie odpowiada; strona sama zapyta ponownie.","term.more":"Pokaż wszystkie wiersze ({n})","term.less":"Pokaż mniej wierszy","term.alt":"Zapytanie do publicznego API i odpowiedź na nie","agol.sec":"{n} sekund temu","agol.sec.few":"{n} sekundy temu","agol.sec.1":"{n} sekundę temu","agol.min":"{n} minut temu","agol.min.few":"{n} minuty temu","agol.min.1":"{n} minutę temu","agol.hours":"{n} godzin temu","agol.hours.few":"{n} godziny temu","agol.hours.1":"{n} godzinę temu","agol.days":"{n} dni temu","agol.days.1":"{n} dzień temu","netp.k":"Sieć na żywo","netp.k.snap":"Sieć w dniu {date}","netp.say.snap":"Najnowszy był blok {h}. Nad następnym pracowało {r}. Obserwujących węzłów: {n}.","netp.lead.snap":"Ostatni stan, jaki otrzymała ta strona. Publiczne API w tej chwili nie odpowiada; strona sama zapyta ponownie.","ex.h1":"Każdy blok jest publiczny.","ex.lead":"Wyszukaj blok, przelew albo adres. Twoja przeglądarka przelicza Proof of Work każdego bloku, który pokazuje.","ex.q.ph":"Blok, hash lub adres","pulse.tip.h":"Ostatnie {n} godz.","pulse.next":"Trwa kopanie bloku {h}. {t} od ostatniego bloku.","pulse.around.h":"W pobliżu bloku {h}","pulse.around.n":"{n} bloków w ciągu tych {k} godz.","pulse.around.n.few":"{n} bloki w ciągu tych {k} godz.","pulse.now":"teraz","pulse.by":"Znaleziony przez {who}","pulse.alt":"Bloki na osi czasu. Każde światło to jeden blok; odstęp między dwoma światłami to czas, który je dzieli.","ex.row.tx":"{n} przelewów","ex.row.tx.few":"{n} przelewy","ex.row.tx.1":"{n} przelew","ex.row.tx0":"brak przelewów","ex.proof.h":"Proof of Work","ex.proof.p":"Miner obraca dwa liczniki w nagłówku, nonce i extranonce, aż hash wszystkich 136 bajtów spadnie poniżej celu. Twoja przeglądarka właśnie powtórzyła to obliczenie.","proof.pick":"Wybierz pole, żeby zobaczyć, co zawiera.","pulse.around.n.1":"{n} blok w ciągu tych {k} godz.","ex.tx.batch":"Płatność zbiorcza","ex.tx.script":"Wydatek z konta ze skryptem","ex.txv.status":"Status","ex.txv.waiting":"Czeka na blok","ex.txv.sumPending":"Wysłano, ale nie ma jeszcze w żadnym bloku.","ex.txv.expected":"Spodziewany w bloku {h}, za około {min} min, o ile nie pojawi się nic z wyższą opłatą.","ex.txv.unknownWhen":"Dalej w kolejce, niż sięga prognoza.","ex.addr.waiting":"Czeka","ex.addr.older":"Wczytaj starsze operacje","ex.next.tag":"w budowie","ex.next.h":"Co jest już pewne","ex.next.reward":"Nagroda","ex.next.pending":"Oczekujące transakcje","ex.next.empty":"Mempool jest pusty, więc ten blok zawiera na razie tylko coinbase.","ex.next.some":"Oczekujące płatności trafią do tego bloku, o ile się zmieszczą.","ex.next.who":"Nie wiadomo jeszcze, kto go znajdzie.","ex.fill":"{p}% pełny","ex.fill.of":"{n} z {max} transakcji","ex.queue.h":"Kolejka","ex.queue.row":"{n} tx · od {fee} · ~{min} min","ex.queue.none":"Nic nie czeka — następny blok weźmie wszystko.","ex.queue.more":"Łącznie transakcji: {n}, bloków: {b}.","ex.queue.note":"Przewidywana kolejność według opłaty za bajt, przy założeniu, że nic nowego nie dojdzie. Opłata dotyczy przelewu bez notatki.","ex.check.h":"Weryfikacja w Twojej przeglądarce","ex.check.note":"Te kontrole odbywają się tutaj, a nie na serwerze.","ex.check.ser":"Serializacja","ex.check.hash":"Hash przeliczony","ex.check.pow":"Proof of Work","ex.check.link":"Powiązanie łańcucha","ex.check.ok":"poprawny","ex.check.bad":"NIEPOPRAWNY","ex.check.open":"otwarty","ex.check.p":"Nagłówek jest odtwarzany z jego pól, hashowany podwójnie, porównywany z zapisaną trudnością, a powiązanie z poprzednim blokiem jest sprawdzane. Te kontrole odbywają się tutaj, a nie na serwerze. To, które bloki są widoczne, pochodzi z lustra serwera; jest ono porównywane z pełnym węzłem, a różnica zostanie tu pokazana. Zielona kropka na bloku oznacza: zweryfikowano tutaj.","ex.f.achieved":"Osiągnięto","ex.f.time":"Czas bloku","ex.f.time.s":"od poprzedniego bloku","ex.verdict.ok":"Zweryfikowano tutaj {n} bloków","ex.verdict.ok.few":"Zweryfikowano tutaj {n} bloki","ex.verdict.ok.1":"Zweryfikowano tutaj {n} blok","ex.verdict.bad":"Jedna z kontroli nie przeszła","ex.verified":"zweryfikowano tutaj","ex.mirror.fork":"Lustro pokazuje na wysokości {h} inny blok niż pełny węzeł. Lista poniżej może dotyczyć innej gałęzi.","ex.mirror.behind":"Lustro jest w tyle za pełnym węzłem (bloki: {n}). Poniżej brakuje najnowszych.","ex.mirror.behind.1":"Lustro jest w tyle za pełnym węzłem (bloki: {n}). Poniżej brakuje najnowszych.","lv.an.apk.akku":"Niektóre urządzenia i tak zamykają aplikacje w tle, żeby oszczędzać baterię. Jeśli mining sam się zatrzymuje, ustaw zużycie baterii przez aplikację na „Bez ograniczeń” (Ustawienia → Aplikacje → YSKAR Wallet → Bateria).","lv.an.apk.dienst":"Od wersji 1.0.9 liczy osobna usługa aplikacji. Mining działa dalej, gdy wyjdziesz z aplikacji albo zablokujesz ekran. W trakcie miningu Android pokazuje powiadomienie z Twoim hashrate; „Zatrzymaj mining” kończy go od razu stamtąd.","lv.an.apk.hintergrund":"Mining w tle","lv.an.apk.inst":"Instalacja","lv.an.apk.knopf":"Pobierz najnowszą wersję","lv.an.apk.m1":"Otwórz zakładkę Mining i przewiń do sekcji „Sterowanie”.","lv.an.apk.m2":"Wybierz tryb: Solo albo Pool. W trybie Pool aplikacja proponuje otwarty pool; po stuknięciu „Zmień” zobaczysz wszystkie poole z liczbą minerów, mocą obliczeniową, znalezionymi blokami i opłatą. Pełnego poola nie da się wybrać.","lv.an.apk.m3":"Ustaw „Workery” i „Obciążenie”. Workery to rdzenie procesora, które liczą; obciążenie określa, jak mocno pracują (od 25 do 100 %).","lv.an.apk.m4":"Stuknij „Uruchom mining”. Jeśli Android zapyta o powiadomienia, zezwól na nie: dzięki temu widzisz, że mining działa, i możesz go stamtąd zatrzymać.","lv.an.apk.name":"Na telefonie ta aplikacja nazywa się „YSKAR Wallet”. To inna aplikacja niż nowy YSKAR Wallet bez miningu; obie można zainstalować obok siebie, a Twoje 12 słów działa w obu.","lv.an.apk.pruefen":"Sprawdzanie pobranego pliku (opcjonalnie)","lv.an.apk.pruefenText":"Każde wydanie zawiera też plik z końcówką <code>.sha256</code>. Jest w nim suma kontrolna APK. Jeśli suma kontrolna Twojego pliku się zgadza, to dokładnie ten plik, który opublikowaliśmy.","lv.an.apk.s1":"Na telefonie otwórz stronę pobierania i stuknij plik <code>yskar-wallet-….apk</code>.","lv.an.apk.s2":"Android zapyta, czy można instalować aplikacje z tego źródła (np. z Twojej przeglądarki). Stuknij „Ustawienia” i zezwól dla tego źródła.","lv.an.apk.s3":"Wróć i stuknij „Zainstaluj”. Google Play Protect może wyświetlić ostrzeżenie; to normalne w przypadku aplikacji spoza Sklepu Play.","lv.an.apk.s4":"Otwórz aplikację, utwórz portfel albo przywróć istniejący za pomocą 12 słów.","lv.an.apk.start":"Uruchamianie miningu","lv.an.apk.text":"Aplikacja na Androida kopie dalej w tle, także przy zablokowanym ekranie, i pokazuje Twój mining w widżecie na ekranie głównym. Ponieważ Google Play nie dopuszcza miningu na urządzeniu, ta wersja jest dostępna bezpośrednio u nas.","lv.an.apk.tipp":"Nasza rada: wszystkie workery, obciążenie 25 %, w poolu. To oszczędza baterię i mniej nagrzewa telefon, a w poolu mniejsze kwoty przychodzą regularniej. „Skalibruj urządzenie” znajdzie najlepszą liczbę workerów dla Twojego telefonu.","lv.an.apk.titel":"Aplikacja na Androida z miningiem","lv.an.apk.update":"Aktualizacja aplikacji","lv.an.apk.updateText":"Gdy pojawi się nowa wersja, aplikacja pokaże informację po otwarciu. Stuknij „Pobierz”: aplikacja pobierze aktualizację, a potem Android zapyta, czy ją zainstalować. Twój portfel zostaje zachowany. Ręcznie sprawdzisz to w aplikacji: Ustawienia → Aplikacja → Aktualizacje.","lv.an.apk.w1":"Przytrzymaj wolne miejsce na ekranie głównym, wybierz „Widżety” i przeciągnij „YSKAR Wallet” na ekran.","lv.an.apk.w2":"Gdy mining działa, widżet pokazuje, ile udało się zarobić w tej sesji, a do tego hashrate, czas pracy i przyjęte share’y. „Stop” zatrzymuje mining prosto z ekranu głównego. Gdy mining jest zatrzymany, widzisz aktualny blok, hashrate sieci i nagrodę za blok.","lv.an.apk.w3":"„Zarobione w tej sesji” liczy nagrody za bloki i wypłaty z poola zaksięgowane na Twoim adresie od startu; wartość zmienia się, gdy zostanie znaleziony nowy blok. Wygląd jasny lub ciemny wybierasz w aplikacji: Ustawienia → Aplikacja → Widżet. Widżet w tej postaci jest dostępny od wersji 1.1.0.","lv.an.apk.widget":"Widżet na ekranie głównym","lv.an.etikett":"Poradniki","lv.an.ex.p1":"Szukaj po wysokości bloku, hashu albo adresie.","lv.an.ex.p2":"Przy każdym bloku widzisz, kto go znalazł: nazwa, pool albo adres solo.","lv.an.ex.p3":"Wpisz własny adres, żeby sprawdzić swoje wypłaty.","lv.an.ex.text":"<a href=\"/explorer\">Explorer</a> pokazuje każdy blok, każdy przelew i każdy adres. Składa na nowo każdy nagłówek bloku w Twojej przeglądarce, hashuje go i sprawdza Proof of Work oraz łańcuch. Przelewy, podpisy i salda sprawdzają pełne węzły: uruchom własny, a nie musisz nikomu wierzyć.","lv.an.ex.titel":"Explorer","lv.an.gr.aus":"Jak wypłaca pool","lv.an.gr.aus1":"Sam blok wypłaca wszystkim bezpośrednio. Operator poola nigdy nie trzyma Twoich pieniędzy i nie ma progu wypłaty.","lv.an.gr.aus2":"Liczy się praca z ostatniego czasu, mierzona w share’ach. Jeśli dopiero zaczynasz, Twoja część pierwszego bloku jest odpowiednio mała.","lv.an.gr.gebuehr":"Operator może pobierać opłatę od 0 do 5%. Jest ona podana na liście pooli.","lv.an.gr.hinweis":"Nikt nie może obiecać Ci zysku. To, jak często coś dostajesz, zależy od Twojej mocy obliczeniowej, od mocy sieci i od przypadku.","lv.an.gr.p1":"YSKAR to własny blockchain. Nowy blok jest znajdowany mniej więcej co 10 minut. Kto go znajdzie, dostaje nagrodę – obecnie 875 YSR – bezpośrednio na swój adres.","lv.an.gr.p2":"Aby znaleźć blok, Twoje urządzenie sprawdza kolejne liczby (podwójne SHA-256). Im większą masz moc obliczeniową, tym większe masz szanse. Trudność dostosowuje się do mocy całej sieci.","lv.an.gr.plaetze":"Jeden blok może wypłacić najwyżej 64 adresom, dlatego pool ma najwyżej 64 miejsca (63, jeśli pobiera prowizję). Miejsce liczy się tylko, gdy kopiesz: nowe urządzenie zajmuje je na próbę przez 2 minuty i zatrzymuje, regularnie dostarczając share’y. Miejsca minerów, którzy przestają kopać, znów się zwalniają.","lv.an.gr.pool":"<strong>Pool:</strong> wiele osób szuka razem. Gdy pool znajdzie blok, nagroda jest dzielona według wniesionej pracy. Mniejsze kwoty, ale bardziej regularnie.","lv.an.gr.solo":"<strong>Solo:</strong> szukasz samodzielnie. Jeśli znajdziesz blok, cała nagroda jest Twoja. To może długo potrwać.","lv.an.gr.sp":"Solo albo pool","lv.an.gr.titel":"Jak działa mining","lv.an.hi.a1":"Android zamyka aplikację, żeby oszczędzać baterię. Ustaw zużycie baterii przez YSKAR Wallet na „Bez ograniczeń” (Ustawienia → Aplikacje → YSKAR Wallet → Bateria).","lv.an.hi.a2":"Pool ma najwyżej 64 miejsca. Miejsce zwalnia się od razu, gdy miner przestaje kopać, i do 20 minut po tym, jak miner przestaje się odzywać, więc ponowna próba później może się udać. W przeciwnym razie wybierz inny pool albo kop solo. Jeśli Twój adres ma już miejsce, kolejne urządzenia nadal mogą dołączyć.","lv.an.hi.a3":"Węzeł nie znalazł jeszcze innego węzła. Sprawdź połączenie z internetem oraz to, czy Node Core dostał zgodę w pytaniu zapory systemu Windows. Potem chwilę poczekaj.","lv.an.hi.a4":"Węzeł jeszcze się synchronizuje. Mining ruszy, gdy przegląd pokaże „In sync”.","lv.an.hi.a5":"Mining na karcie graficznej wymaga karty NVIDIA, AMD lub Intel z aktualnym sterownikiem. Zainstaluj aktualny sterownik producenta i uruchom Node Core ponownie. Przed kopaniem każda karta wykonuje autotest; karta, która go nie przejdzie, nie jest używana.","lv.an.hi.a6":"Przywróć portfel za pomocą tych samych 12 słów, w tej samej kolejności. Inny zestaw słów to inny portfel.","lv.an.hi.a7":"Pytania zadawaj na <a href=\"https://t.me/+GxAmtTMeG1w1M2Yy\">czacie społeczności na Telegramie</a>. Błędy zgłaszaj na <a href=\"https://github.com/dabitlex/YSKAR/issues\">GitHubie</a>. Nigdy nie podawaj swoich 12 słów: administratorzy nigdy nie piszą do Ciebie pierwsi.","lv.an.hi.f1":"Mining na telefonie sam się zatrzymuje","lv.an.hi.f2":"„Pool full”","lv.an.hi.f3":"Node Core: „No peer connected yet”","lv.an.hi.f4":"Node Core: mining się nie uruchamia","lv.an.hi.f5":"Karta graficzna nie została znaleziona","lv.an.hi.f6":"Na nowym urządzeniu brakuje mojego salda","lv.an.hi.f7":"Coś innego","lv.an.hi.titel":"Gdy coś nie działa","lv.an.mini.hinweis":"Wskazówka: w zakładce Mining możesz wybrać solo albo pool. W poolu dostajesz mniejsze kwoty, ale częściej; solo oznacza rzadsze, ale całe bloki.","lv.an.mini.s1":"Otwórz <a href=\"https://t.me/YSKAR_bot\">@YSKAR_bot</a> w Telegramie i uruchom aplikację.","lv.an.mini.s2":"Stuknij „Utwórz portfel”. Aplikacja pokaże Ci 12 słów: zapisz je na papierze, po kolei.","lv.an.mini.s3":"Potwierdź kilka słów i wybierz PIN.","lv.an.mini.s4":"Otwórz zakładkę Mining i stuknij „Uruchom mining”. Nie zamykaj aplikacji, gdy liczy.","lv.an.mini.text":"Najszybszy start. Mini App działa w Telegramie; nie trzeba niczego instalować.","lv.an.mini.titel":"Telegram Mini App","lv.an.nc.e1":"<strong>Węzeł:</strong> folder danych, porty i seed są już wypełnione. Wartości domyślne pasują większości osób – po prostu kliknij „Continue”.","lv.an.nc.e2":"<strong>Portfel:</strong> utwórz nowy portfel i zapisz 12 słów albo przenieś istniejący portfel za pomocą swoich 12 słów. Wybierz hasło o długości co najmniej 8 znaków; szyfruje ono słowa na tym PC. Portfel możesz też skonfigurować później.","lv.an.nc.e3":"<strong>Start:</strong> kliknij „Start node”.","lv.an.nc.einst":"Ustawienia","lv.an.nc.erst":"Pierwsze uruchomienie","lv.an.nc.firewall":"Przy pierwszym uruchomieniu Windows pyta, czy Node Core może korzystać z sieci. Zezwól na to, inaczej węzeł nie znajdzie innych węzłów.","lv.an.nc.firewallLinux":"W Linux to pytanie się nie pojawia. Jeśli działa zapora (np. ufw), otwórz port 8646 – inaczej inne węzły nie dotrą do Twojego. Twoje własne połączenia działają tak czy inaczej.","lv.an.nc.i1":"Pobierz instalator i uruchom go.","lv.an.nc.i2":"Windows pokazuje komunikat „System Windows ochronił ten komputer”, bo instalator nie jest podpisany. Wybierz „Więcej informacji”, a potem „Uruchom mimo to”.","lv.an.nc.i3":"Postępuj zgodnie z instrukcjami instalatora. Potem uruchomi się Node Core.","lv.an.nc.inst":"Instalacja w Windows","lv.an.nc.l1":"<strong>Ubuntu, Debian, Linux Mint:</strong> pobierz plik <code>.deb</code> i zainstaluj go w terminalu. Potem uruchom „YSKAR Node Core” z menu aplikacji.","lv.an.nc.l2":"<strong>Inne dystrybucje:</strong> pobierz AppImage, nadaj mu prawo wykonywania i uruchom. AppImage wymaga FUSE 2 (w Ubuntu pakiet <code>libfuse2</code>).","lv.an.nc.l3":"Node Core dla Linux działa na 64-bitowych komputerach (x86-64) ze środowiskiem graficznym. Komputery ARM, takie jak Raspberry Pi, nie są obsługiwane.","lv.an.nc.linux":"Instalacja w Linux","lv.an.nc.m1":"Wybierz cel: Solo albo Pool. W trybie Pool wybierz pool z listy albo wpisz adres w polu „Your own pool address” i sprawdź go.","lv.an.nc.m2":"„Reward goes to”: Twój własny portfel albo inny adres.","lv.an.nc.m3":"Wybierz urządzenie: procesor, karta graficzna albo jedno i drugie. Ustaw liczbę rdzeni i obciążenie na rdzeń.","lv.an.nc.m4":"Tylko solo: jeśli chcesz, wpisz nazwę, która pojawi się w znalezionych przez Ciebie blokach. Jest publiczna i zostaje na stałe.","lv.an.nc.m5":"Kliknij „Start mining”.","lv.an.nc.mining":"Mining","lv.an.nc.poolHinweis":"Jeśli pool już Cię nie przyjmuje, mining zatrzymuje się i podaje powód. Nigdy nie kopie po cichu dalej solo.","lv.an.nc.port":"Czy muszę otworzyć port?","lv.an.nc.portText":"Nie. Bez tego Twój węzeł sam łączy się z innymi węzłami. Jeśli otworzysz port 8646 w routerze, inne węzły będą mogły połączyć się także z Twoim. To pomaga sieci, ale jest opcjonalne.","lv.an.nc.pruefen":"Aby mieć pewność, że plik jest tym, który opublikowaliśmy, porównaj jego sumę kontrolną z plikiem <code>.sha256</code> z wydania. W PowerShell:","lv.an.nc.pruefenLinux":"W Linux:","lv.an.nc.s1":"<strong>Uruchamianie z Windows</strong> (w Linux: „Uruchamiaj po zalogowaniu”): Node Core uruchamia się bez okna, gdy się logujesz.","lv.an.nc.s2":"<strong>Działanie po zamknięciu:</strong> okno znika do obszaru powiadomień obok zegara, a węzeł pracuje dalej.","lv.an.nc.s3":"<strong>Wznawianie miningu po uruchomieniu:</strong> mining działa dalej z ostatnimi ustawieniami, gdy tylko węzeł jest zsynchronizowany.","lv.an.nc.s4":"<strong>Aktualizacje:</strong> Node Core informuje, gdy dostępna jest nowa wersja. Nic nie instaluje się samo.","lv.an.nc.sig":"Podpisywanie i YSKAR Lab","lv.an.nc.sigText":"Od wersji 1.1.0 „Podpisz” w portfelu podpisuje tekst Twoim adresem, na przykład aby udowodnić, że adres należy do Ciebie; „Sprawdź” weryfikuje podpisaną wiadomość innej osoby. Na <a href=\"https://lab.yskar.app\">lab.yskar.app</a> „Zaloguj portfelem” otwiera Node Core: pokazuje stronę, Twój adres i czas ważności prośby, a podpisuje dopiero po potwierdzeniu hasłem. Podpis nie może przenieść YSR.","lv.an.nc.sync":"Pierwsza synchronizacja","lv.an.nc.syncText":"Przy pierwszym uruchomieniu Node Core pobiera cały blockchain i sprawdza każdy blok. To może chwilę potrwać; postęp widać w przeglądzie. Mining rusza dopiero wtedy, gdy węzeł dogoni sieć.","lv.an.nc.text":"Node Core to program YSKAR dla Windows i Linux: własny węzeł z portfelem i miningiem w jednym oknie. Pobiera blockchain na Twój PC i sam sprawdza każdy blok.","lv.an.nc.titel":"Node Core dla Windows i Linux","lv.an.nc.update":"Aktualizacja","lv.an.nc.updateText":"Pobierz nowy instalator, zamknij Node Core – także w obszarze powiadomień – i uruchom instalator. Twój portfel i blockchain zostają zachowane.","lv.an.nc.v1":"Windows 10 lub 11 (64-bit) albo Linux (64-bit, x86-64) i połączenie z internetem","lv.an.nc.v2":"Miejsce na dysku na blockchain. Jest jeszcze mały i rośnie z każdym blokiem.","lv.an.nc.v3":"Do miningu na karcie graficznej: karta NVIDIA, AMD lub Intel z aktualnym sterownikiem. Bez niej liczy procesor.","lv.an.nc.vor":"Czego potrzebujesz","lv.an.nc.w1":"<strong>Wysyłanie:</strong> wpisz odbiorcę i kwotę, sprawdź, potwierdź hasłem. Hasło jest wymagane przed każdym przelewem.","lv.an.nc.w2":"<strong>Odbieranie:</strong> pokaż swój adres albo jego kod QR.","lv.an.nc.w3":"<strong>Kontakty:</strong> nazwy zamiast adresów, zapisane tylko na tym PC.","lv.an.nc.w4":"<strong>Blokada:</strong> portfel blokuje się sam po 10 minutach bez aktywności oraz zawsze, gdy Windows zostaje zablokowany. Czas zmienisz w ustawieniach.","lv.an.nc.wallet":"Portfel","lv.an.node.s1":"1. Zbuduj","lv.an.node.s2":"2. Uruchom i połącz z siecią","lv.an.node.s2Text":"Węzeł łączy się z innym węzłem (seedem), pobiera łańcuch i sprawdza go blok po bloku. Inne węzły mogą połączyć się z Twoim na porcie 8646, jeśli otworzysz go w routerze; to opcjonalne. Z opcją --no-upstream Twój węzeł przekazuje bloki tylko innym węzłom, a nie serwerowi WWW projektu.","lv.an.node.s3":"3. Kop na własnym węźle","lv.an.node.s4":"4. Uruchom pool (opcjonalnie)","lv.an.node.s4Fuss":"--pool-fee podaje się w punktach bazowych: 100 = 1,00 %, maksymalnie 500.","lv.an.node.s4Mehr":"To, czego potrzebuje pool, żeby aplikacja i inni minerzy mogli się z nim połączyć, opisano w sekcji <a href=\"/anleitungen#pool\">Prowadzenie poola</a>.","lv.an.node.s4Text":"Każdy węzeł może być poolem, bez rejestracji. Sam blok wypłaca wszystkim uczestnikom; nigdy nie trzymasz cudzych środków.","lv.an.node.s5":"5. Jako usługa na Raspberry Pi","lv.an.node.s5Text":"Aby węzeł sam startował po restarcie, skonfiguruj go jako usługę systemd. Gotowe pliki i instrukcja są w repozytorium w <a href=\"https://github.com/dabitlex/YSKAR/tree/main/deploy\"><code>deploy/</code></a>.","lv.an.node.text":"Pełny węzeł pobiera łańcuch i sam sprawdza każdy blok – Proof of Work, podpisy, salda. Wymaga Node.js 22.13 lub nowszego i dobrze działa na Raspberry Pi.","lv.an.node.titel":"Uruchamianie pełnego węzła","lv.an.node.win":"Na Windowsie użyj npm.cmd zamiast npm.","lv.an.pc.s1":"1. Zainstaluj Node.js","lv.an.pc.s1Text":"Miner wymaga Node.js 20 lub nowszego. Pobierz wersję LTS ze strony <a href=\"https://nodejs.org\">nodejs.org</a> i zainstaluj ją. Na Windowsie otwórz potem nowe okno wiersza poleceń.","lv.an.pc.s2":"2. Pobierz minera","lv.an.pc.s2Text":"Nie trzeba instalować niczego więcej. Autotest sprawdza, czy Twój komputer poprawnie liczy hashe.","lv.an.pc.s3":"3. Zacznij mining","lv.an.pc.s3Text":"Zastąp adres swoim własnym adresem YSKAR (zaczyna się od ysr1). Z poolem:","lv.an.pc.s4":"4. Karta graficzna (opcjonalnie)","lv.an.pc.s4Text":"Z kartą graficzną dodaj <code>--gpu</code>. Potrzebny jest program GPU: <code>yskar-cuda</code> dla kart NVIDIA, <code>yskar-opencl</code> dla kart AMD i Intel. Miner używa pierwszego, który znajdzie kartę; <code>--gpu-api opencl</code> wybiera program dla AMD i Intel nawet przy obecnej karcie NVIDIA. Dla Linux oba są dołączone do każdego wydania Node Core (<code>yskar-cuda-…-linux-x86_64</code>, <code>yskar-opencl-…-linux-x86_64</code>); w Windows zbuduj je zgodnie z opisem w repozytorium w <code>node-core/gpu</code>.","lv.an.pc.s5":"5. Koparki z HiveOS","lv.an.pc.s5Text":"Dla koparek z HiveOS jest gotowy pakiet: ten miner z programem GPU, jeden miner na każdą kartę NVIDIA, AMD lub Intel, bez opłat. Jest dołączony do każdego wydania Node Core jako <code>yskar-hiveos-….tar.gz</code>. Konfiguracja flight sheet jest opisana w <a href=\"https://github.com/dabitlex/YSKAR/blob/main/hiveos/README.md\">hiveos/README.md</a>.","lv.an.pc.solo":"Solo zamiast poola: pomiń --mode pool. Całe bloki, ale rzadziej.","lv.an.pc.text":"Miner działa na Windowsie, macOS i Linuksie. Potrzebuje tylko adresu – bez klucza prywatnego, bez portfela, bez rejestracji. Możesz go bezpiecznie uruchomić na dowolnym komputerze.","lv.an.pc.titel":"Miner na PC","lv.an.pool.beitritt":"Jak dołączają minerzy","lv.an.pool.beitrittText":"W aplikacji wybierz „Pool” i wpisz adres swojego poola w opcji „Własny adres”; w Node Core – w polu „Your own pool address”. W minerze na PC:","lv.an.pool.caddy":"Konfiguracja dla Caddy. Zastąp nazwę swoją; musi ona wcześniej wskazywać na Twój komputer.","lv.an.pool.g1":"<strong>Nazwa:</strong> od 3 do 32 prostych znaków. Jest zapisywana w każdym bloku Twojego poola i zostaje tam na zawsze.","lv.an.pool.g2":"<strong>Opłata:</strong> od 0 do 5%. W poleceniu <code>--pool-fee</code> podaje się w punktach bazowych: 100 = 1%. Przy opłacie musisz podać adres, na który ona trafia.","lv.an.pool.g3":"<strong>Miejsca:</strong> najwyżej 64 adresy, z opłatą 63 – jednym odbiorcą jesteś Ty.","lv.an.pool.g4":"<strong>Żadnych cudzych pieniędzy:</strong> blok wypłaca wszystkim bezpośrednio. Nigdy nie trzymasz środków swoich minerów.","lv.an.pool.h1":"Otwórz „Run a pool”, ustaw nazwę, opłatę i liczbę miejsc, a potem włącz pool.","lv.an.pool.h2":"W części Mining wybierz „Pool”. Twój własny pool jest na liście pierwszy.","lv.an.pool.h3":"Dla kolejnych PC włącz „Devices in your home network”. Łączą się one przez <code>http://&lt;adres tego PC&gt;:8645</code>.","lv.an.pool.heim":"W sieci domowej z Node Core","lv.an.pool.heimText":"Pool w Node Core odpowiada tylko Twojemu własnemu PC i Twojej własnej sieci. Z internetu nie jest w ten sposób dostępny.","lv.an.pool.k1":"Kto kopie z Tobą","lv.an.pool.k2":"Czego potrzebujesz","lv.an.pool.liste":"Jak trafić na listę pooli","lv.an.pool.listeText":"Aplikacja i Node Core pokazują utrzymywaną listę pooli. Aby pool został wpisany, musi być dostępny przez HTTPS i odpowiadać na <code>/api/v2/pool</code>. Poproś o wpis na <a href=\"https://github.com/dabitlex/YSKAR/issues\">GitHubie</a>. Lista nie jest ani kontrolą, ani rekomendacją: liczbę minerów, moc i opłatę pool podaje sam.","lv.an.pool.n1":"<strong>Węzeł, który działa cały czas.</strong> Najlepszy jest węzeł z wiersza poleceń na Raspberry Pi albo na serwerze; zobacz <a href=\"/anleitungen#fullnode\">Uruchamianie pełnego węzła</a>.","lv.an.pool.n2":"<strong>Nazwa</strong>, pod którą jest dostępny: własna domena albo darmowa nazwa DynDNS.","lv.an.pool.n3":"<strong>HTTPS z ważnym certyfikatem.</strong> Telegram i przeglądarki nie wczytują niczego nieszyfrowanego. Bez HTTPS żaden telefon nie połączy się z Twoim poolem.","lv.an.pool.n4":"<strong>Serwer WWW przed węzłem</strong>, który pobiera certyfikat i przekazuje żądania do węzła, na przykład Caddy.","lv.an.pool.n5":"<strong>Otwarty port 443.</strong> Przy węźle w domu oznacza to przekierowanie portu w routerze.","lv.an.pool.netz":"Dla aplikacji, Mini App i minerów z internetu","lv.an.pool.netzText":"Oto czego potrzebujesz:","lv.an.pool.o1":"<strong>W domu:</strong> bez dodatkowych kosztów. Ale Twój adres IP staje się publicznie znany, potrzebujesz przekierowania portu, a obciążenie spada na Twoje łącze.","lv.an.pool.o2":"<strong>Wynajęty serwer:</strong> Twój domowy adres IP pozostaje poza tym, a na serwerze nie ma żadnych kluczy – tylko adres dla opłaty. Najpierw przeczytaj warunki dostawcy: wielu zabrania miningu i wszystkiego, co się z nim wiąże. Uzyskaj zgodę na piśmie.","lv.an.pool.ort":"W domu czy na wynajętym serwerze?","lv.an.pool.r1a":"Ty i urządzenia w Twojej sieci domowej","lv.an.pool.r1b":"Node Core z włączoną opcją „Run a pool”","lv.an.pool.r2a":"Minery na PC z internetu","lv.an.pool.r2b":"Węzeł, który działa cały czas i jest dostępny z zewnątrz","lv.an.pool.r3a":"Aplikacja i Mini App","lv.an.pool.r3b":"Dodatkowo HTTPS: nazwa (domena albo DynDNS) i certyfikat","lv.an.pool.regeln":"Zasady dla każdego poola","lv.an.pool.start":"Uruchom węzeł jako pool. Nasłuchuje tylko na samym komputerze; przed nim stoi serwer WWW.","lv.an.pool.test":"Sprawdź z zewnątrz. Jeśli odpowiedź zawiera nazwę Twojego poola i liczbę miejsc, pool jest dostępny.","lv.an.pool.text":"Pool w YSKAR nie jest usługą z kontami. To węzeł, który dzieli nagrodę ze swoich bloków. Każdy może go prowadzić, bez rejestracji. To, czego potrzebujesz, zależy od tego, kto ma u Ciebie kopać.","lv.an.pool.titel":"Prowadzenie poola","lv.an.si.p1":"<strong>Twoje 12 słów to Twój portfel.</strong> Nigdy nie wpisuj ich na żadnej stronie internetowej i nigdy nikomu ich nie wysyłaj. Nikt z YSKAR o nie nie poprosi.","lv.an.si.p2":"<strong>Pobieraj tylko z yskar.app i z projektu YSKAR na GitHubie.</strong> Jeśli chcesz mieć pewność, porównaj sumę kontrolną.","lv.an.si.p3":"<strong>Aktualizuj swoje oprogramowanie.</strong> Przy zapowiedzianej zmianie reguł nieaktualny węzeł albo zatrzymuje się na tym bloku, albo działa dalej, nie sprawdzając nowej reguły – w obu przypadkach warto zaktualizować na czas.","lv.an.si.p4":"<strong>Prowadzenie węzła:</strong> inne węzły widzą Twój adres IP, jak w każdej sieci peer-to-peer. Przekierowanie portu nie jest potrzebne. Jeśli nie chcesz, żeby Twój adres był widoczny, użyj VPN.","lv.an.si.p5":"<strong>Node Core:</strong> portfel i interfejs są dostępne tylko z Twojego własnego PC.","lv.an.si.titel":"Bezpieczeństwo","lv.an.text":"Wszystko wyjaśnione krok po kroku: mining na telefonie i na PC, Twój portfel, własny węzeł i własny pool.","lv.an.titel":"Krok po kroku","lv.an.tocLabel":"Na tej stronie","lv.an.ue.k1":"Sposób","lv.an.ue.k2":"Do czego","lv.an.ue.k3":"Czego potrzebujesz","lv.an.ue.r1a":"Telegram Mini App","lv.an.ue.r1b":"Wypróbowanie, od razu","lv.an.ue.r1c":"Telegram","lv.an.ue.r2a":"Aplikacja na Androida","lv.an.ue.r2b":"Mining w tle na telefonie","lv.an.ue.r2c":"Telefon z Androidem","lv.an.ue.r3a":"Node Core","lv.an.ue.r3b":"Własny węzeł z portfelem i miningiem na PC, także z kartą graficzną","lv.an.ue.r3c":"Windows 10/11 lub Linux (64-bit)","lv.an.ue.r4a":"Miner na PC","lv.an.ue.r4b":"Mining z wiersza poleceń","lv.an.ue.r4c":"Windows, macOS lub Linux z Node.js","lv.an.ue.r5a":"Full node","lv.an.ue.r5b":"Węzeł albo pool na Raspberry Pi lub serwerze","lv.an.ue.r5c":"Linux, Windows lub macOS z Node.js 22.13 lub nowszym","lv.an.ue.text":"Jest pięć sposobów, żeby dołączyć. Wszystkie korzystają z tego samego portfela: za pomocą 12 słów wszędzie masz dostęp do tego samego salda.","lv.an.ue.titel":"Który sposób Ci odpowiada?","lv.an.w.empfangen":"Odbieranie","lv.an.w.empfangenText":"Pokaż swój adres albo jego kod QR. Do kodu możesz dodać kwotę i notatkę; nadawca musi wtedy tylko potwierdzić. Swój adres możesz podać każdemu – swoich 12 słów nikomu.","lv.an.w.kontakte":"Kontakty i historia","lv.an.w.kontakteText":"Kontakty nadają adresom nazwy; są zapisane tylko na Twoim urządzeniu. Historia pokazuje każdą płatność; nagrody z miningu z jednego dnia są zebrane w jednym wierszu i można je rozwinąć aż do pojedynczego bloku.","lv.an.w.s1":"Odbiorca: wklej adres, zeskanuj kod QR albo wybierz kontakt. Adres YSKAR zaczyna się od ysr1.","lv.an.w.s2":"Kwota i, jeśli chcesz, notatka do 32 bajtów – to 32 zwykłe litery łacińskie, mniej z polskimi znakami lub innym alfabetem. Notatka jest zapisana publicznie w blockchainie.","lv.an.w.s3":"Opłata: aplikacja ją proponuje. Gdy w sieci nie ma tłoku, opłata minimalna wystarczy na następny blok.","lv.an.w.s4":"Sprawdzenie: aplikacja pokazuje pełny adres i mówi Ci, czy wysyłasz na niego pierwszy raz. Potwierdź PIN-em albo odciskiem palca.","lv.an.w.senden":"Wysyłanie","lv.an.w.warn":"Wysłanej płatności nie da się cofnąć. Sprawdź cały adres, zanim potwierdzisz.","lv.an.wallet.p1":"Zapisz słowa na papierze, we właściwej kolejności. Bez zrzutów ekranu, bez chmury.","lv.an.wallet.p2":"Przechowuj kartkę w bezpiecznym miejscu. Jeśli zgubisz telefon, słowa przywrócą wszystko.","lv.an.wallet.p3":"PIN chroni tylko aplikację na tym urządzeniu. Nie zastąpi słów.","lv.an.wallet.p4":"Aby przenieść się na nowe urządzenie, wybierz „Mam już dwanaście słów” i wpisz je.","lv.an.wallet.text":"Twój portfel powstaje na Twoim urządzeniu z 12 słów. Te słowa są Twoim kluczem: kto je ma, ma dostęp do środków – na każdym urządzeniu, w każdej aplikacji YSKAR.","lv.an.wallet.titel":"Twój portfel","lv.fuss.datenschutz":"Prywatność","lv.fuss.impressum":"Nota prawna","lv.hood.f2.k":"Trudność","lv.nc.appimage":"AppImage dla innych dystrybucji Linux","lv.nc.bildNotiz":"Widok przykładowy – liczby są przykładami.","lv.nc.knopfLinux":"Pobierz dla Linux (.deb)","lv.nc.knopfWin":"Pobierz dla Windows","lv.nc.mehr":"Suma kontrolna i informacje o wersji","lv.nc.system":"Windows 10 lub 11 (64-bit)","lv.nc.systemLinux":"Linux 64-bit · Ubuntu, Debian, Mint","lv.pr.block.alt":"136-bajtowy nagłówek bloku i jego dziesięć pól","lv.pr.block.merkle":"Jeden hash ze wszystkich transakcji w bloku. Zmienia go jeden zmieniony bajt w dowolnym przelewie.","lv.pr.block.nonce":"Liczba, którą zmieniają minerzy. Pierwsze 128 bajtów pozostaje takie samo w obrębie zadania, więc każda próba wymaga tylko dwóch kroków kompresji SHA-256.","lv.pr.block.prev":"Hash poprzedniego bloku. Łączy łańcuch: zmiana starego bloku zmieniłaby każdy hash po nim.","lv.pr.block.state":"Jeden hash ze wszystkich kont (saldo i nonce) po tym bloku. Każdy węzeł sam go oblicza i porównuje.","lv.pr.block.text":"Każdy blok zaczyna się od dokładnie 136 bajtów. Jego hash to podwójne SHA-256 z tych bajtów i nie może przekraczać celu wyznaczonego przez trudność.","lv.pr.block.titel":"Budowa nagłówka bloku","lv.pr.db.ablauf":"Wygaśnięcie","lv.pr.db.ablaufWert":"opcjonalne, według wysokości bloku","lv.pr.db.adresse":"Adres","lv.pr.db.adresseWert":"ysr1…, 42 znaki; konta wspólne od V6: ysr1p…, 63 znaki (bech32m)","lv.pr.db.blockzeitWert":"600 sekund (cel)","lv.pr.db.diffWert":"LWMA z 45 bloków, po każdym bloku","lv.pr.db.einheit":"Najmniejsza jednostka","lv.pr.db.gebuehr":"Opłaty trafiają do","lv.pr.db.gebuehrWert":"minera bloku","lv.pr.db.kette":"Łańcuch","lv.pr.db.knoten":"Pełne węzły","lv.pr.db.knotenWert":"każdy przechowuje i sprawdza cały łańcuch","lv.pr.db.konsens":"Konsensus","lv.pr.db.konsensWert":"Proof of Work, SHA-256d","lv.pr.db.memo":"Notatka (memo)","lv.pr.db.memoWert":"do 32 bajtów","lv.pr.db.minGeb":"Minimalna opłata (konsensus)","lv.pr.db.minGebWert":"1 jednostka za bajt","lv.pr.db.modell":"Model","lv.pr.db.modellWert":"konta z saldem i nonce","lv.pr.db.muenze":"Moneta","lv.pr.db.name":"Nazwa · symbol","lv.pr.db.netz":"Sieć","lv.pr.db.notfall":"Reguła awaryjna","lv.pr.db.notfallWert":"łatwiej po 30 min bez bloku","lv.pr.db.nullkonto":"Adres spalania","lv.pr.db.pfad":"Wyprowadzanie kluczy","lv.pr.db.pool":"Poole","lv.pr.db.poolWert":"wypłata z bloku, opłata 0–5 %","lv.pr.db.relay":"Minimalna opłata do przekazania","lv.pr.db.relayWert":"10 jednostek za bajt","lv.pr.db.sig":"Podpisy","lv.pr.db.staub":"Najmniejsza kwota do wysłania","lv.pr.db.staubWert":"100 jednostek","lv.pr.db.transfer":"Rozmiar przelewu","lv.pr.db.transferWert":"od 168 do 200 bajtów","lv.pr.db.tx":"Transakcje na blok","lv.pr.db.txWert":"do 2000","lv.pr.db.vorab":"Pre-mine · przydział","lv.pr.db.vorabWert":"brak","lv.pr.db.wahl":"Wybór łańcucha","lv.pr.db.wahlWert":"najwięcej skumulowanej pracy","lv.pr.db.wallet":"Portfele i konta","lv.pr.db.worte":"Słowa seed","lv.pr.db.worteWert":"BIP39, 12 lub 24 słowa","lv.pr.etikett":"Protokół w szczegółach","lv.pr.gen.belohnung":"Nagroda","lv.pr.gen.belohnungWert":"875 YSR, niewydawalne","lv.pr.gen.text":"Pierwszy blok łańcucha. Jego coinbase zawiera krótką wiadomość, a nagroda trafiła na adres, z którego nikt nie może niczego wydać.","lv.pr.gen.titel":"Blok 0","lv.pr.gen.zeit":"Znacznik czasu","lv.pr.pruefen":"Sprawdź sam blok 0 albo najnowszy blok, prosto w swojej przeglądarce.","lv.pr.text":"Wszystko poniżej jest zapisane w kodzie konsensusu i takie samo dla każdego węzła. Nic nie zależy od serwera, firmy ani ustawienia.","lv.pr.titel1":"YSKAR i YSR,","lv.pr.titel2":"bajt po bajcie.","lv.pr.tx.alt":"Pola przelewu","lv.pr.tx.p1":"Podpis obejmuje też chain ID, więc przelew podpisany dla YSKAR jest nieważny w każdej innej sieci.","lv.pr.tx.p2":"Nonce liczy przelewy wysłane z konta. Ten sam przelew nigdy nie może zostać wykonany dwa razy.","lv.pr.tx.p3":"Opcjonalna wysokość wygaśnięcia sprawia, że przelew traci ważność, jeśli do tego czasu nie trafi do bloku.","lv.pr.tx.text":"Przelew przenosi YSR z jednego konta na drugie. Ma 168 bajtów plus opcjonalną notatkę.","lv.pr.tx.titel":"Budowa przelewu","lv.recht.nurDeutsch":"Ta strona jest w języku niemieckim, zgodnie z wymogami prawa niemieckiego.","lv.supply.aera.fuss":"Nagrody liczone są w całych jednostkach bazowych (0,00000001 YSR), więc przy każdym halvingu reszta odpada: łącznie zostanie wyemitowanych 20 999 999,99832 YSR, nieco poniżej maksimum.","lv.supply.aera.k1":"Era","lv.supply.aera.k2":"Bloki","lv.supply.aera.k3":"Nagroda za blok","lv.supply.aera.k4":"Wyemitowano w erze","lv.supply.aera.k5":"Łącznie po erze","lv.supply.aera.text":"Era trwa 12 000 bloków, około 83 dni. W każdej erze nagroda jest o połowę mniejsza niż w poprzedniej. Od bloku 444 000 nie powstają już nowe YSR, a minerzy otrzymują tylko opłaty.","lv.supply.aera.titel":"Emisja według ery","lv.wallet.warnung":"<strong>Kto ma 12 słów, ten ma środki.</strong> Nigdy ich nikomu nie podawaj. Nikt z YSKAR nigdy Cię o nie nie poprosi.","lv.wpseite.drucken":"Drukuj / zapisz jako PDF","lv.wpseite.toc":"Spis treści","lv.wpseite.untertitel":"Blockchain Proof of Work, który każdy może kopać i każdy może zweryfikować.","lv.zahlen.blockzeit":"Czas bloku","lv.wpseite.nurDeEn":"Whitepaper jest obecnie dostępny po angielsku i po niemiecku.","unit.min":"{n} min","unit.hours":"{n} godz.","unit.days":"{n} dni","ago.sec":"{n} s temu","ago.min":"{n} min temu","ago.hours":"{n} godz. temu","ago.days":"{n} dni temu","eta.around":"za około {d}, mniej więcej {date}","v6.active":"Aktywna od bloku 10 000","v6.pending":"pozostało bloków: {n}","mode.live":"Na żywo z łańcucha","mode.snapshot":"Stan z {date}","mode.history":"Historia do bloku {h}","mode.liveShort":"Dostępne","mode.snapshotShort":"Ostatni znany stan","dur.years":"{n} lat","dur.years.1":"{n} rok","dur.years.few":"{n} lata","dur.years.frac":"{n} roku","dur.years.big":"{n} lat","dur.days":"{n} dni","dur.days.1":"{n} dzień","dur.hours":"{n} godzin","dur.hours.1":"{n} godzinę","dur.hours.few":"{n} godziny","dur.min":"{n} minut","dur.min.1":"{n} minutę","dur.min.few":"{n} minuty","dur.sec":"{n} sekund","dur.sec.few":"{n} sekundy","dur.sec.1":"{n} sekundę","rm.run.p":"Wydane i w użyciu. Każda pozycja prowadzi do miejsca, w którym możesz to sprawdzić.","rm.run.1.h":"Sieć główna","rm.run.1.p":"Bloki od 9 wrz 2026. Łańcuch jest na bloku","rm.run.1.l":"Sieć na żywo","rm.run.2.h":"Wersje konsensusu od 2 do 5","rm.run.2.p":"Aktywne od bloków 2000, 4000, 6000 i 7000.","rm.run.2.l":"Co zmieniła każda z nich","rm.run.3.p":"Pełny węzeł, portfel, mining na CPU i GPU oraz prowadzenie poola dla Windows i Linuksa.","rm.run.3.l":"Pobierz","rm.run.4.p":"Portfel na Androida: wysyłaj, odbieraj, podpisuj. Gotowy na wersję 6.","rm.run.4.l":"O portfelu","rm.run.5.h":"Trzy publiczne poole","rm.run.5.p":"YSKAR MAIN, Gozero i ODW.Serv. Oprogramowanie poola jest otwarte; każdy może uruchomić własny.","rm.run.5.l":"Poole na żywo","rm.run.6.h":"Explorer i publiczne API","rm.run.6.p":"Każdy blok, przelew i adres, w przeglądarce i przez HTTP.","rm.run.6.l":"Otwórz explorer","rm.run.7.p":"Propozycje, dyskusja i status, wszystko jawnie. Logujesz się swoim portfelem.","rm.fix.p":"Te zmiany są zapisane w kodzie konsensusu. Wchodzą w życie w określonym bloku, a nie w określonym dniu: to, kiedy ten blok nadejdzie, zależy od tego, jak szybko znajdowane są bloki.","rm.fix.blocks":"bloków","rm.fix.1.at":"Blok 10 000","rm.fix.1.h":"Wersja 6","rm.fix.1.p":"Konta wspólne z maksymalnie 16 kluczami, blokady czasowe i blokady hashowe, przelewy zbiorcze do maksymalnie 1000 odbiorców oraz miejsce na 5000 transakcji w bloku. Hard fork ustalony po głosowaniu społeczności 25 paź 2026. Przed tym blokiem węzły muszą mieć aktualne wydanie.","rm.fix.1.l":"Co zmienia się w bloku 10 000","rm.fix.2.at":"Blok 12 000","rm.fix.2.h":"Pierwszy halving","rm.fix.2.p":"Nagroda za blok spada z 875 do 437,5 YSR. Zmniejsza się o połowę co kolejne 12 000 bloków.","rm.fix.2.l":"Cały harmonogram","rm.fix.after":"Ostatni nowy YSR powstanie w bloku 443 999. Potem minerzy zarabiają już tylko na opłatach.","rm.plan.p":"Zamierzone, nie obiecane. Nic tutaj nie ma daty, a kolejność może się zmienić.","rm.plan.1.h":"Swapy i płatności natychmiastowe","rm.plan.1.p":"Wersja 6 wnosi do łańcucha elementy podstawowe: blokady hashowe i blokady czasowe. Funkcje portfela, które używają ich do swapów i płatności w czasie rzeczywistym, pojawią się później.","rm.plan.2.h":"Stratum dla koparek","rm.plan.2.p":"Dziś minerzy i poole używają własnego protokołu HTTP YSKAR. Stratum jest planowane na czas, gdy sieć urośnie.","rm.plan.3.h":"Mining na konta wspólne","rm.plan.3.p":"Wersja 6 nie może wypłacić nagrody za blok na konto wspólne. Specyfikacja zostawia to wersji 7.","rm.plan.4.h":"Portfel z własnym węzłem","rm.plan.4.p":"Dziś YSKAR Wallet odczytuje salda z publicznego serwera. W planach: skierowanie go na pełny węzeł, który prowadzisz samodzielnie.","rm.plan.5.h":"YSKAR Wallet w Sklepie Play","rm.plan.5.p":"Dziś portfel to plik APK z GitHub Releases.","rm.plan.6.h":"Publiczna sieć testowa i decyzje społeczności","rm.plan.6.p":"Kolejne etapy YSKAR Lab: wypróbowywanie zmian, zanim trafią do sieci głównej, i wspólne decydowanie o nich.","rm.plan.7.h":"Notowania na giełdach","rm.plan.7.p":"W przygotowaniu, bez daty i bez nazw. Dziś YSR nie ma ceny ani rynku i nikt nie powinien kopać w oczekiwaniu, że to się zmieni.","rm.how.p":"Propozycje są pisane, omawiane i śledzone publicznie w YSKAR Lab. Zmiana zasad konsensusu wymaga specyfikacji, a do sieci głównej trafia dopiero na wysokości bloku, którą każdy węzeł zna z góry.","com.ch.p":"Ogłoszenia pojawiają się najpierw na kanale Telegram. Wszystko inne służy do pytań i dyskusji.","com.ch.1":"Wydania i nowości.","com.ch.2":"Pytania i dyskusja z innymi minerami i użytkownikami.","com.ch.3":"Krótkie aktualności od @yskar_official.","com.ch.4":"Wątek z ogłoszeniami.","com.ch.5":"Kod źródłowy, wydania i zgłoszenia.","com.ch.6":"Propozycje, od pierwszego pomysłu do wydania.","com.do.1.h":"Uruchom pełny węzeł","com.do.1.p":"Każdy węzeł, który sam sprawdza bloki, sprawia, że sieć mniej zależy od pojedynczego serwera.","com.do.2.h":"Kop, samodzielnie albo w poolu","com.do.2.p":"Moc obliczeniowa rozłożona na wielu minerów i kilka pooli sprawia, że łańcuchem trudniej sterować.","com.do.3.h":"Prowadź pool","com.do.3.p":"Oprogramowanie poola jest częścią repozytorium i płaci minerom w samym bloku. Kolejny niezależny pool jeszcze bardziej rozprasza moc obliczeniową.","com.do.4.h":"Testuj i zgłaszaj","com.do.4.p":"Wypróbuj wydanie i załóż zgłoszenie dla tego, co nie działa. Napisz, co widzisz i jak to odtworzyć.","com.do.5.h":"Proponuj i dyskutuj","com.do.5.p":"Przynieś pomysł do YSKAR Lab albo ulepsz czyjś w komentarzach.","com.lab.p":"Każda propozycja przechodzi przez te same sześć etapów i każdy widzi, na którym jest.","com.lab.s1":"Pomysł","com.lab.s1.d":"Podziel się tym, co masz na myśli.","com.lab.s2":"Dyskusja","com.lab.s2.d":"Ulepszajcie go wspólnie w komentarzach.","com.lab.s3":"Szkic","com.lab.s3.d":"Tekst, projekt, specyfikacja lub kod.","com.lab.s4":"Planowane","com.lab.s4.d":"Ustalone na jedno z kolejnych wydań, z uzasadnieniem.","com.lab.s5":"W sieci testowej","com.lab.s5.d":"Wypróbuj, zanim trafi do sieci głównej.","com.lab.s6":"Wydane","com.lab.s6.d":"Wydane, z linkiem.","com.lab.k1":"Autor przeprowadza propozycję przez pierwsze trzy etapy.","com.lab.k2":"Od etapu „Planowane” etap ustala zespół, zawsze z uzasadnieniem.","com.lab.open":"Otwórz YSKAR Lab","com.safe.1.h":"Twoje 12 słów zostaje u Ciebie","com.safe.1.p":"Nikt z YSKAR nigdy nie poprosi o Twoje 12 słów, Twój PIN ani plik portfela. Kto o nie prosi, próbuje zabrać Twoje monety.","com.safe.2.h":"Pobieraj ze źródła","com.safe.2.p":"Pobieraj oprogramowanie z wydań na GitHubie, do których prowadzi ta strona, i przed instalacją porównaj odcisk certyfikatu portfela.","com.safe.3.h":"Żadnych obietnic","com.safe.3.p":"YSR nie ma dziś ceny ani rynku i nie jest notowany na żadnej giełdzie. Nic tutaj nie obiecuje, że to się zmieni.","com.channel":"Kanał na Telegramie","com.chat":"Czat społeczności","wallet.dl":"Pobierz APK","wallet.meta":"Wersja 2.0.0, dla Androida 7 lub nowszego. Open source na licencji MIT. Po angielsku i niemiecku.","wallet.feat.p":"Bez reklam, bez śledzenia i bez konta u kogokolwiek. Aplikacja rozmawia z siecią YSKAR i z niczym innym.","wallet.f1.h":"Twój klucz zostaje u Ciebie","wallet.f1.p":"Portfel powstaje w Twoim telefonie. 12 słów odzyskiwania przywraca go na dowolnym urządzeniu. Są przechowywane w chronionej pamięci Androida, zaszyfrowane Twoim PIN-em, i nigdy nie trafiają do kopii w chmurze.","wallet.f2.h":"Wysyłaj świadomie","wallet.f2.p":"Wpisz adres, wybierz kontakt albo zeskanuj kod QR. Przed wysłaniem jeszcze raz widzisz odbiorcę, kwotę i opłatę sieciową, a potem potwierdzasz kodem PIN albo odciskiem palca. Przelewu nie da się cofnąć.","wallet.f3.h":"Odbieraj","wallet.f3.p":"Pokaż swój kod QR albo skopiuj i udostępnij swój adres. Każdy może go zobaczyć: sama znajomość adresu nie wystarczy, żeby cokolwiek wypłacić.","wallet.f5.h":"Podpisuj i loguj się","wallet.f5.p":"Udowodnij podpisaną wiadomością, że adres należy do Ciebie, i sprawdzaj podpisy innych. Zaloguj się do YSKAR Lab kodem QR. Podpis nie może przenieść YSR.","wallet.f6.h":"Dobrze zabezpieczony","wallet.f6.p":"PIN i odcisk palca, automatyczna blokada po wybranym czasie, brak zrzutów ekranu, gdy na ekranie widać 12 słów, oraz własna klawiatura aplikacji, dzięki której nic z tego, co wpisujesz, nie przechodzi przez aplikację klawiatury w telefonie.","wallet.inst.h":"Instalacja w czterech krokach","wallet.inst.p":"Portfel jest rozprowadzany jako plik APK przez wydania na GitHubie. Aktualizacje instalują się na poprzedniej wersji, a Twój portfel zostaje na urządzeniu.","wallet.inst.1":"Otwórz <a class='ext' href='https://github.com/dabitlex/YSKAR--WALLET/releases/latest' target='_blank' rel='noopener'>najnowsze wydanie</a> na telefonie z Androidem i pobierz plik <code>yskar-wallet-…apk</code>.","wallet.inst.2":"Otwórz plik. Zezwól na instalację z tego źródła, gdy Android o to zapyta.","wallet.inst.3":"Dotknij „Create wallet” i zapisz 12 słów na papierze, po kolei.","wallet.inst.4":"Wybierz PIN. Aby przenieść istniejący portfel, wpisz zamiast tego jego 12 słów.","wallet.verify.h":"Sprawdź, czy plik jest prawdziwy","wallet.verify.p":"Każde wydanie jest podpisane tym samym kluczem. To odcisk SHA-256 jego certyfikatu. Jeśli odcisk pobranego pliku jest inny, nie instaluj go.","wallet.oth.h":"Inne miejsca dla Twoich YSR","wallet.oth.p":"Każda aplikacja YSKAR używa tych samych 12 słów. Dzięki nim wszędzie masz dostęp do tego samego salda.","wallet.oth.1.h":"YSKAR Wallet","wallet.oth.1.p":"Android. Wysyłanie, odbieranie, podpisywanie. Nie kopie.","wallet.oth.2.h":"Node Core","wallet.oth.2.p":"Windows i Linux. Portfel wewnątrz Twojego własnego pełnego węzła, z miningiem i podpisywaniem wiadomości. <a href='/mining#setup'>Pobierz Node Core</a>","wallet.oth.3.h":"Aplikacja na Androida z miningiem","wallet.oth.3.p":"Portfel i mining w telefonie, z widżetem na ekranie głównym i powiadomieniami.","wallet.oth.4.h":"Telegram Mini App","wallet.oth.4.p":"Najłatwiejsze wejście, bez instalowania czegokolwiek. Własność zależy od Twoich 12 słów, a nie od konta w Telegramie.","wallet.st.h":"Na jakim etapie jest portfel","wallet.st.1.h":"Tylko Android","wallet.st.1.p":"Portfel to plik APK z GitHuba. Nie ma go w żadnym sklepie z aplikacjami i nie ma aplikacji na iOS.","wallet.st.2.h":"Gotowy na wersję 6","wallet.st.2.p":"Wersja 2.0.0 zna nowy format przelewu i przełącza się na niego w bloku 10 000. Starsza wersja nadal odbiera YSR, ale po tym bloku nie może wysyłać.","wallet.st.3.h":"Planowane: sklep z aplikacjami","wallet.st.3.p":"Planowane jest wydanie w Google Play. Nie ma terminu.","wallet.st.4.h":"Planowane: własny węzeł","wallet.st.4.p":"Dziś portfel czyta dane z głównego węzła projektu. W planach jest podłączenie go do węzła, który prowadzisz samodzielnie, żeby nikt nie musiał wierzyć projektowi na słowo w sprawie salda.","mining.ways.p":"Każda droga jest darmowa i korzysta z tego samego portfela: dzięki swoim 12 słowom wszędzie masz dostęp do tych samych YSR.","mining.tab.pc":"PC","mining.tab.phone":"Telefon","mining.tab.cli":"Wiersz poleceń","mining.tab.rig":"Miner","mining.pc.h":"Node Core dla Windows i Linux","mining.pc.p":"Pełny węzeł, portfel i miner w jednym programie. Node Core sam sprawdza każdy blok i kopie Twoim procesorem oraz kartami graficznymi NVIDIA, AMD i Intel. Wersja 1.1.0, dla Windows 10 i 11 oraz dla 64-bitowego Linuksa.","mining.pc.s1":"Pobierz instalator i uruchom go.","mining.pc.s2":"Utwórz portfel i zapisz 12 słów albo przenieś swój portfel za ich pomocą.","mining.pc.s3":"W zakładce Mining wybierz solo albo pool, wskaż procesor lub kartę graficzną i uruchom.","mining.pc.win":"Pobierz dla Windows","mining.pc.deb":"Pobierz dla Linux (.deb)","mining.pc.more":"Dostępne są też: <a class='ext' href='https://github.com/dabitlex/YSKAR/releases/download/node-core-v1.1.0/YSKAR-Node-Core-1.1.0-x86_64.AppImage' target='_blank' rel='noopener'>AppImage</a> dla innych dystrybucji Linuksa oraz <a class='ext' href='https://github.com/dabitlex/YSKAR/releases/tag/node-core-v1.1.0' target='_blank' rel='noopener'>informacje o wydaniu z sumami kontrolnymi</a>.","mining.pc.note":"<strong>Instalator dla Windows nie jest podpisany.</strong> Dlatego Windows zapyta jeden raz: wybierz „Więcej informacji”, a potem „Uruchom mimo to”. Porównaj sumę kontrolną z informacjami o wydaniu, jeśli chcesz mieć pewność, że plik jest tym opublikowanym.","mining.pc.imgcap":"Node Core, przegląd. Liczby na obrazku są przykładowe.","mining.phone.h":"W telefonie","mining.phone.p":"Najłatwiejszy sposób, żeby poznać YSKAR. Telefon wnosi niewiele mocy obliczeniowej i znajduje bloki tylko w poolu. Poważny mining odbywa się na komputerach i koparkach.","mining.phone.s1":"Zainstaluj aplikację na Androida z GitHuba albo otwórz Mini App w Telegramie.","mining.phone.s2":"Utwórz portfel i zapisz 12 słów na papierze.","mining.phone.s3":"Wybierz pool i zacznij kopać.","mining.phone.apk":"Aplikacja na Androida z miningiem","mining.phone.tg":"Mini App w Telegramie","mining.phone.f1":"Aplikacja na Androida","mining.phone.f1.v":"Kopie dalej w tle, także przy zablokowanym ekranie, i pokazuje status w widżecie na ekranie głównym. Rozprowadzana jako plik APK, bo sklepy z aplikacjami nie pozwalają na mining na urządzeniu.","mining.phone.f2":"Mini App","mining.phone.f2.v":"Nic do instalowania. Działa wewnątrz Telegrama, dopóki jest otwarty. Twoje monety zależą od Twoich 12 słów, a nie od konta w Telegramie.","mining.phone.f3":"YSKAR Wallet","mining.phone.f3.v":"Aplikacja portfela nie kopie. Służy do wysyłania, odbierania i podpisywania.","mining.cli.h":"Miner z wiersza poleceń","mining.cli.p":"Dla Windows, macOS i Linuksa. Miner potrzebuje tylko adresu: bez klucza, bez portfela i bez rejestracji. Możesz go uruchomić na komputerze, nad którym nie masz kontroli.","mining.cli.f1":"Wymagania","mining.cli.f1.v":"Node.js 20 lub nowszy, nic więcej do instalowania","mining.cli.f2":"Karty graficzne","mining.cli.f2.v":"dodaj <code>--gpu</code>. Używa <code>yskar-cuda</code> dla NVIDIA oraz <code>yskar-opencl</code> dla AMD i Intela","mining.cli.f3":"Solo","mining.cli.f3.v":"kop na własnym pełnym węźle i pomiń <code>--mode pool</code>","mining.cli.link":"Pełny poradnik do minera","mining.cli.c1":"pobierz minera i przetestuj ten komputer","mining.cli.c2":"kop w publicznym poolu","mining.cli.c3":"albo solo, na własnym węźle","mining.cli.addr":"Zastąp <code>ysr1...</code> własnym adresem. Nagrody trafiają prosto na niego.","mining.rig.h":"Koparki z HiveOS","mining.rig.p":"Gotowy pakiet dla HiveOS: miner z wiersza poleceń z programami GPU, jeden miner na kartę graficzną.","mining.rig.dl":"Pobierz pakiet 1.1.0","mining.rig.doc":"Flight sheet i konfiguracja","mining.rig.f1":"Karty","mining.rig.f1.v":"NVIDIA (CUDA), AMD i Intel (OpenCL)","mining.rig.f2":"Opłata","mining.rig.f2.v":"brak w minerze. Pool pobiera własną opłatę","mining.rig.f3":"Konfiguracja","mining.rig.f3.v":"Twój adres i pool wpisujesz we flight sheet. Poradnik pokazuje każde pole","mining.return":"<strong>Nikt nie może obiecać Ci zysku.</strong> To, jak często coś otrzymujesz, zależy od Twojej mocy obliczeniowej, od mocy całej sieci i od przypadku. YSR nie ma ceny rynkowej.","pools.p1":"Solo szukasz samodzielnie i zatrzymujesz całą nagrodę za blok, który znajdziesz. W poolu wielu szuka razem, a nagroda jest dzielona według pracy, jaką wykonał każdy z nich.","pools.p2":"Pool YSKAR nie jest usługą z kontami. To węzeł, którego bloki płacą każdemu minerowi bezpośrednio, w samym bloku. Operator nigdy nie przechowuje cudzych monet i nie ma progu wypłaty.","pools.reported":"zgłoszono {r}","pools.c5":"Z ostatnich {n}","pools.full":"pełny","pools.cap":"Minerzy, miejsca i hashrate to dane, które każdy pool sam o sobie zgłasza. Udział w ostatnich {n} blokach jest liczony z łańcucha.","pools.f1":"Rozliczenie","pools.f1.v":"Według udziałów z niedawnej przeszłości (PPLNS). Jeśli dopiero zaczynasz, Twoja część pierwszego bloku jest mała.","pools.f2":"Miejsca","pools.f2.v":"Blok może zapłacić najwyżej 64 adresom, więc pool ma 63 miejsca plus opłatę operatora. Od wersji 6 będzie ich 254.","pools.f3":"Opłata","pools.f3.v":"Ustalana przez operatora, od 0 do 5 %.","pools.f4":"Własny pool","pools.f4.v":"Każdy węzeł może być poolem, bez rejestracji. <a class='ext' href='https://github.com/dabitlex/YSKAR/blob/main/docs/POOL.md' target='_blank' rel='noopener'>Jak go prowadzić</a>","calc.p":"Wpisz swój hashrate. Szacunek opiera się na pracy w najnowszych blokach łańcucha, a nie na liczbach, które poole same o sobie zgłaszają. Node Core i miner pokazują Twój hashrate podczas pracy.","calc.unit":"Jednostka","calc.mode":"Jak kopiesz","calc.pool":"W poolu","calc.solo":"Solo","calc.which":"Pool","calc.day":"Dziennie, średnio","calc.week":"Na 7 dni","calc.month":"Na 30 dni","calc.share":"Twój udział w sieci","calc.d.every":"Średnio jeden blok co","calc.d.chance":"Szansa na co najmniej jeden blok w ciągu 24 godzin","calc.d.block":"Za każdy znaleziony blok","calc.d.poolEvery":"Pool znajduje blok mniej więcej co","calc.d.part":"Twoja część każdego bloku poola","calc.d.fee":"Opłata poola, już odliczona","calc.d.poolShare":"Udział poola w ostatnich {n} blokach","calc.d.net":"Hashrate sieci z ostatnich {n} bloków","calc.enter":"Wpisz hashrate większy od 0.","calc.note":"Szacunek, nie obietnica. Bloki znajduje się przypadkiem, a trudność podąża za całą siecią. Opłaty nie są wliczone.","calc.halving":"Do halvingu w bloku {b} pozostało około {d} dni. Wartości dla 7 i 30 dni uwzględniają już połowę nagrody po nim.","calc.halving.1":"Do halvingu w bloku {b} pozostał około {d} dzień. Wartości dla 7 i 30 dni uwzględniają już połowę nagrody po nim.","calc.every.min":"{n} minut","calc.every.min.few":"{n} minuty","calc.every.min.1":"{n} minutę","calc.every.hours":"{n} godzin","calc.every.hours.1":"{n} godzinę","calc.every.hours.few":"{n} godziny","calc.every.hours.frac":"{n} godziny","calc.every.days":"{n} dni","calc.every.days.1":"{n} dzień","calc.every.days.frac":"{n} dnia","calc.every.years":"{n} lat","calc.every.years.1":"{n} rok","calc.every.years.few":"{n} lata","calc.every.years.frac":"{n} roku","net.hashrate":"Hashrate sieci","net.difficulty":"Trudność","net.now":"W tej chwili","net.height":"Wysokość bloku","net.fromChain":"praca ostatnich 24 bloków podzielona przez ich czas","net.everyBlock":"przeliczana dla każdego bloku","net.blocktime":"Czas bloku, ostatnie 50 bloków","net.target600":"cel: 600 s","net.mempool":"Oczekujące przelewy","net.fromNode":"w węźle głównym","net.miners":"Aktywni minerzy","net.sessions":"Sesje miningu","net.nodes":"Zgłaszające się węzły","net.reported":"zgłoszone, nie do sprawdzenia","net.next.v6":"Wersja 6 w bloku 10 000","net.next.halving":"Pierwszy halving w bloku 12 000","net.hist.h":"Historia odczytana z bloków","net.hist.p":"Każdy blok łańcucha, zsumowany według dni w UTC. Historia jest kompletna do bloku <span data-live='snapTip'></span>; liczby powyżej są odczytywane na żywo.","net.range":"Okres","net.range.all":"Od bloku 0","net.range.30":"30 dni","net.range.7":"7 dni","net.c.hash":"Hashrate na dzień","net.c.hash.capLog":"Praca bloków z danego dnia podzielona przez ich czas. Skala logarytmiczna: każda linia to dziesięć razy więcej niż ta poniżej.","net.c.hash.capLin":"Praca bloków z danego dnia podzielona przez ich czas.","net.c.blocks":"Bloki na dzień","net.c.blocks.cap":"Tylko pełne dni. Przy docelowym czasie bloku dzień ma 144 bloki.","net.c.blocks.ref":"Cel: 144 bloki na dzień","net.c.blocks.name":"bloki","net.c.finders":"Bloki na dzień, według znalazcy","net.c.finders.cap":"Tylko pełne dni. Bloki pooli mają w łańcuchu nazwę poola; blok, który płaci jednemu adresowi, liczy się jako solo.","net.c.time":"Średni czas bloku na dzień","net.c.time.cap":"Sekundy między blokami, uśrednione w ciągu dnia.","net.c.time.ref":"Cel: 600 sekund","net.c.day":"Dzień (UTC)","net.s.main":"YSKAR MAIN","net.s.gozero":"Gozero","net.s.solo":"Solo","net.find.h":"Kto znajduje bloki","net.find.p1":"W pierwszych tygodniach każdy blok znajdowano solo. Dziś prawie wszystkie bloki pochodzą z dwóch pooli, a większość z jednego.","net.find.p2":"To ma znaczenie. Operator poola wybiera transakcje i blok nadrzędny każdego bloku, nad którym pool pracuje, a kto kieruje większością mocy obliczeniowej, może zbudować łańcuch o największej pracy. Więcej pooli i więcej minerów solo sprawia, że łańcuchem trudniej sterować.","net.find.link":"Poole i jak prowadzić własny","net.find.title":"Udział w znalezionych blokach","net.find.last":"Ostatnie {n} bloków","net.find.last1000":"1000 bloków do bloku {h}","net.find.allb":"Wszystkie bloki do bloku {h}","net.find.cap":"Policzone z łańcucha. Pierwszy słupek podąża za łańcuchem na żywo, pozostałe dwa kończą się tam, gdzie kończy się historia wbudowana w stronę.","net.blocks.h":"Najnowsze bloki","net.blocks.p":"Wybierz blok, żeby zobaczyć jego nagłówek, przeliczyć jego Proof of Work i przeczytać jego transakcje.","net.blocks.link":"Otwórz explorer","net.blocks.title":"Od najnowszych","net.b.height":"Wysokość","net.b.age":"Znaleziono","net.b.by":"Znalazca","net.b.paid":"Wypłacono na","net.b.diff":"Trudność","net.b.solo":"solo","net.b.addr":"{n} adresów","net.b.addr.few":"{n} adresy","net.b.addr.1":"{n} adres","net.src.h":"Skąd pochodzą liczby","net.src.p":"Nie każda liczba na tej stronie ma tę samą wagę.","net.src.1.h":"Z łańcucha","net.src.1.p":"Wysokość, trudność, podaż i każdy wykres na tej stronie. Hashrate to praca w najnowszych blokach podzielona przez czas, jaki zajęły. Każdy, kto prowadzi pełny węzeł, może to wszystko przeliczyć.","net.src.2.h":"Zgłoszone","net.src.2.p":"Aktywni minerzy, sesje, węzły i hashrate, który pool podaje sam o sobie. To dane deklarowane. Pokazują kierunek, ale nikt nie może ich sprawdzić.","net.src.3.h":"Lustro","net.src.3.p":"Ta strona i explorer czytają kopię łańcucha z bazy danych, żeby szybko się ładować. Lustro sprawdza każdy blok, który zapisuje, ale to tylko udogodnienie. Łańcuch to to, co do czego zgadzają się pełne węzły.","net.src.4.h":"Węzły seed","net.src.4.p":"Nowy węzeł najpierw łączy się z <code>pool.yskar.app:8646</code> albo <code>yskar-seed2.dynv6.net:8646</code>. Oba prowadzi ten sam operator. Potem węzły wymieniają się między sobą adresami innych węzłów.","ex.q.label":"Przeszukaj łańcuch","ex.q.go":"Szukaj","ex.try":"Na początek:","ex.try.0":"blok 0","ex.try.burn":"spalenie w bloku 3974","ex.try.or":"albo","ex.try.zero":"adres, z którego nikt nie może nic wydać","ex.crumb":"Explorer","ex.msg.empty":"Wpisz wysokość bloku, hash bloku, ID transakcji albo adres.","ex.msg.badAddr":"Ten adres zawiera literówkę: jego suma kontrolna się nie zgadza. Sprawdź go znak po znaku.","ex.msg.addrShape":"To nie jest adres YSKAR. Adresy zaczynają się od ysr1 i mają 42 znaki.","ex.msg.tooHigh":"Blok {h} jeszcze nie istnieje. Łańcuch jest na bloku {tip}.","ex.msg.notFound":"W łańcuchu nic do tego nie pasuje.","ex.msg.offlineHash":"Łańcuch teraz nie odpowiada, więc nie da się wyszukać tego hasha. Spróbuj ponownie za chwilę.","ex.msg.searching":"Przeszukiwanie łańcucha.","ex.msg.badLink":"Ten link nie prowadzi do bloku, transakcji ani adresu.","ex.loading":"Odczytywanie z łańcucha.","ex.missing.h":"Łańcuch teraz nie odpowiada","ex.missing.p":"Explorer odczytuje każdy blok, przelew i adres z publicznego API YSKAR, a to zapytanie właśnie się nie powiodło. Spróbuje ponownie sam, gdy tylko łańcuch odpowie.","ex.missing.link":"Spróbuj ponownie teraz","ex.none.block":"W łańcuchu nie ma bloku {h}. Łańcuch jest na bloku {tip}.","ex.none.tx":"Nie jest znana żadna transakcja o tym ID: nie ma jej w żadnym bloku i nie czeka na blok. Jeśli została wysłana przed chwilą, ta strona sama sprawdzi ponownie.","ex.back":"Wróć do najnowszych bloków","ex.latest.h":"Najnowsze bloki","ex.latest.snap":"Łańcuch teraz nie odpowiada. To najnowsze bloki ({n}) według ostatniej odpowiedzi.","ex.latest.live":"Odczytane z publicznego API i odświeżane co 45 sekund.","ex.older":"Pokaż starsze bloki","ex.older.busy":"Odczytywanie","ex.c.height":"Wysokość","ex.c.found":"Znaleziono","ex.c.by":"Znalazca","ex.c.transfers":"Przelewy","ex.c.size":"Rozmiar","ex.c.hash":"Hash bloku","ex.solo":"Miner solo","ex.bytes":"{n} B","ex.block.h":"Blok {h}","ex.prev":"Poprzedni blok","ex.next":"Następny blok","ex.block.sumPool":"Znaleziony {date}, {ago}, przez pool {who}.","ex.block.sumSolo":"Znaleziony {date}, {ago}, przez minera solo.","ex.block.sumGenesis":"Pierwszy blok łańcucha, z datą {date}. Jego nagroda trafiła na adres, z którego nikt nie może nic wydać.","ex.block.partial":"Łańcuch teraz nie odpowiada. To nagłówek bloku w takiej postaci, w jakiej strona już go miała, więc nadal możesz sprawdzić jego Proof of Work. Transakcje pojawią się, gdy tylko łańcuch odpowie.","ex.block.values":"Co zawiera nagłówek","ex.block.values.p":"Te wartości są upakowane w 136 bajtach powyżej. Zmień jedną z nich, a hash przestanie pasować.","ex.f.hash":"Hash bloku","ex.f.prev":"Poprzedni blok","ex.f.prev.none":"Brak. To pierwszy blok.","ex.f.merkle":"Korzeń Merkle’a","ex.f.merkle.s":"Odcisk transakcji w tym bloku","ex.f.state":"Korzeń stanu","ex.f.state.s":"Odcisk wszystkich sald po tym bloku","ex.f.diff":"Trudność","ex.f.diff.s":"Średnio potrzeba było około {n} prób","ex.f.nonce":"Nonce i extranonce","ex.f.nonce.s":"Dwa liczniki, które miner zmieniał, aż hash zaczął pasować","ex.f.size":"Rozmiar","ex.f.size.v":"{n} B z {tx} transakcjami","ex.f.size.v.1":"{n} B z {tx} transakcją","ex.txs.h":"Transakcje w tym bloku","ex.txs.p":"Pierwsza tworzy nagrodę za blok. Każda następna to przelew podpisany przez nadawcę.","ex.tx.coinbase":"Nagroda za blok","ex.tx.transfer":"Przelew","ex.tx.other":"Transakcja typu {type}","ex.tx.new":"Nowo utworzone: {a}","ex.tx.newFees":"Nowo utworzone: {a}, opłaty: {f}","ex.tx.from":"Od","ex.tx.to":"Do","ex.tx.amount":"Kwota","ex.tx.fee":"Opłata","ex.tx.memo":"Notatka","ex.tx.memoHex":"Notatka (bajty)","ex.tx.nonce":"Licznik nadawcy","ex.tx.nonce.s":"Każdy przelew z danego adresu ma kolejny numer, więc żadnego nie da się powtórzyć","ex.tx.id":"ID transakcji","ex.tx.paid":"Wypłacono w samym bloku. Liczba adresów: {n}. Pool nigdy nie trzymał tych monet.","ex.tx.c.addr":"Adres","ex.tx.c.amount":"Kwota w YSR","ex.tx.c.share":"Udział","ex.unspendable":"nie do wydania","ex.txv.sum":"Potwierdzono w bloku {h}, {date}.","ex.txv.block":"Blok","ex.txv.until":"Wygaśnięcie","ex.txv.until.none":"Nie ustawiono wygaśnięcia","ex.txv.until.h":"Blok {h}","ex.txv.size":"Rozmiar","ex.txv.raw":"Bajty w takiej postaci, w jakiej są w bloku","ex.txv.raw.p":"Węzeł sprawdza dokładnie te bajty: podpis, saldo nadawcy i licznik.","ex.txv.how":"Jak zbudowany jest przelew","ex.addr.h":"Adres","ex.addr.zero":"Nikt nie ma klucza do tego adresu. Tego, co tu trafi, nie da się już nigdy wydać.","ex.addr.balance":"Saldo","ex.addr.sent":"Wysłane przelewy","ex.addr.first":"Pierwsze pojawienie się","ex.addr.last":"Ostatnia aktywność","ex.addr.blockN":"Blok {h}","ex.addr.solo":"Otrzymane nagrody za blok","ex.addr.pool":"Otrzymane wypłaty z poola","ex.addr.hist":"Ostatnie operacje","ex.addr.more":"Najnowsze wpisy: {n}.","ex.addr.none":"Łańcuch nie ma jeszcze żadnego wpisu dla tego adresu. Adres jest ważny, gdy tylko istnieje jego klucz; łańcuch dowiaduje się o nim przy pierwszej płatności.","ex.h.block":"Blok","ex.h.when":"Kiedy","ex.h.what":"Co","ex.h.with":"Z kim","ex.h.amount":"Kwota","ex.h.fee":"Opłata","ex.k.in":"Otrzymano","ex.k.out":"Wysłano","ex.k.reward":"Nagroda za blok","ex.k.pool":"Wypłata z poola","ex.copy.addr":"Kopiuj adres","ex.copy.id":"Kopiuj ID","ex.block.sumPoolNoName":"Znaleziony {date}, {ago}, przez pool.","dev.node.h":"Uruchom pełny węzeł","dev.node.p":"Pełny węzeł przechowuje własną kopię łańcucha i sam sprawdza każdy blok. Niczego nie przyjmuje na wiarę, ani od innych węzłów, ani od tej strony.","dev.node.link":"Co węzeł sprawdza w każdym bloku","dev.node.c1":"Pobierz kod źródłowy i zbuduj węzeł","dev.node.c2":"Uruchom go: łączy się z węzłami seed, pobiera łańcuch i sprawdza każdy blok","dev.node.c3":"Kop na własnym węźle, w drugim terminalu","dev.node.f1.k":"Czego potrzebujesz","dev.node.f1.v":"Node.js 22.13 lub nowszy oraz Git. Węzeł zapisuje łańcuch za pomocą modułu SQLite wbudowanego w Node.js.","dev.node.f2.k":"Porty","dev.node.f2.v":"TCP 8646 dla innych węzłów, 8645 dla interfejsu HTTP, z którego korzystają minery i portfele.","dev.node.f3.k":"Zegar","dev.node.f3.v":"Pilnuj, żeby zegar systemowy był dokładny. Blok z datą wyprzedzającą zegar Twojego węzła o ponad 120 sekund zostaje odrzucony.","dev.node.f4.k":"Węzły seed","dev.node.f4.v":"Węzeł z wiersza poleceń nie ma wbudowanego seeda. Podaj oba węzły seed, tak jak w poleceniu powyżej.","dev.node.f5.k":"<code>--no-upstream</code>","dev.node.f5.v":"Powinno znaleźć się w poleceniu. Bez tego węzeł wymieniałby bloki także z lustrem projektu w bazie danych, które przyjmuje bloki tylko od węzła głównego.","dev.node.core":"W systemie Windows w PowerShellu wpisz <code>npm.cmd</code> zamiast <code>npm</code>. Jeśli wolisz okno niż terminal, <a href=\"/node#core\">Node Core</a> uruchamia ten sam pełny węzeł w systemach Windows i Linux.","dev.api.h":"Czytaj łańcuch przez HTTP","dev.api.p":"Publiczne API odpowiada na zwykłe zapytania GET w formacie JSON. Wybierz zapytanie i przeczytaj odpowiedź.","dev.api.title":"Konsola API","dev.api.pick":"Zapytania","dev.api.out":"Odpowiedź","dev.api.run":"Wyślij ponownie","dev.api.curl":"Kopiuj jako curl","dev.api.busy":"Czekam na odpowiedź.","dev.api.ok":"{status} w {ms} ms, odpowiedź na żywo z www.yskar.app.","dev.api.fail":"Zapytanie nie powiodło się ({why}). Widzisz ostatnią odpowiedź, jaką otrzymała ta strona, z {date}.","dev.api.e.summary":"Wysokość, trudność, hashrate, podaż","dev.api.e.blocks":"Najnowsze bloki, od najnowszego","dev.api.e.block":"Jeden blok ze wszystkimi transakcjami","dev.api.e.tx":"Jedna transakcja po jej ID","dev.api.e.account":"Saldo i historia adresu","dev.api.e.search":"Czym jest ten tekst?","dev.api.e.fees":"Opłata, jakiej przelew potrzebuje w tej chwili","dev.api.e.pools":"Poole i liczby, które same zgłaszają","dev.api.e.supply":"Wykopane, nie do wydania i w obiegu","dev.api.e.circ":"Podaż w obiegu jako zwykła liczba","dev.api.n1.h":"Tylko do odczytu i otwarte","dev.api.n1.p":"Bez klucza i bez konta. Zapytania z innych domen są dozwolone, więc strona internetowa może wywoływać API bezpośrednio.","dev.api.n2.h":"Twój własny węzeł też odpowiada","dev.api.n2.p":"Każdy pełny węzeł udostępnia te same ścieżki odczytu na porcie 8645. Skieruj swój kod na <code>http://127.0.0.1:8645</code>, a nie będziesz zależeć od niczyjego serwera.","dev.api.n3.h":"Kwoty to liczby całkowite","dev.api.n3.p":"Kwoty są podawane w jednostkach: 1 YSR to 100 000 000 jednostek. Odczytuj je jako liczby całkowite lub ciągi znaków, nigdy jako liczby zmiennoprzecinkowe.","dev.docs.h":"Dokumenty","dev.docs.p":"Napisane dla tych, którzy chcą sprawdzić, czy to wszystko się zgadza. Każdy odsyła do kodu, który opisuje.","dev.docs.v6":"Wiążąca specyfikacja wersji 6, aktywnej od bloku 10 000.","dev.docs.fullnode":"Pełny węzeł z wiersza poleceń: polecenia, opcje, interfejs HTTP, przechowywanie danych i reorganizacje.","dev.docs.p2p":"Protokół, którym węzły rozmawiają między sobą.","dev.docs.fees":"Zasady opłat i sposób szacowania opłaty.","dev.docs.pool":"Poole: jak dołączyć, jak prowadzić własny i jak działa rozliczanie.","dev.docs.ops":"Publiczna infrastruktura: węzeł główny, HTTPS, lustro i jego ustawienia.","dev.repo.h":"Co gdzie leży","dev.repo.p":"Jedno repozytorium zawiera kod konsensusu, węzeł, minera i testy, które ich pilnują.","dev.repo.core":"Konsensus: nagłówek, trudność, transakcje, stan, wyprowadzanie kluczy portfela","dev.repo.fullnode":"Pełny węzeł: łańcuch, mempool, interfejs miningu, API odczytu, wiersz poleceń","dev.repo.p2p":"Protokół między węzłami","dev.repo.pool":"Rozliczanie PPLNS i podział nagrody za blok","dev.repo.node":"Build pełnego węzła z wiersza poleceń","dev.repo.nodecore":"Node Core dla systemów Windows i Linux, z minerami GPU","dev.repo.miner":"Miner z wiersza poleceń, bez zależności","dev.repo.observer":"Obserwator: małe narzędzie tylko do odczytu, które pobiera łańcuch i przelicza każdy blok","dev.repo.tests":"Testy konsensusu, węzła, P2P, poola i portfela","dev.repo.docs":"Dokumentacja wymieniona powyżej","dev.repo.c1":"Z katalogu głównego repozytorium: zainstaluj, uruchom testy, sprawdź typy","dev.sign.h":"Podpisane wiadomości","dev.sign.p":"Portfel może udowodnić, że kontroluje adres, nie ruszając ani jednej monety. Całe oprogramowanie YSKAR podpisuje i sprawdza ten sam format tekstu.","dev.sign.1":"Podpis to Ed25519 nad surowymi bajtami UTF-8 całej wiadomości, sprawdzany według tej samej reguły co w łańcuchu.","dev.sign.2":"Pierwsza linia zapewnia bezpieczeństwo: transakcja jest binarna i nigdy nie zaczyna się od tych słów, więc podpisana wiadomość nigdy nie może zostać uznana za przelew.","dev.sign.3":"YSKAR Wallet i Node Core podpisują takie wiadomości. YSKAR Lab używa ich, żeby zalogować Cię bez hasła.","dev.con.h":"Współtwórz i zgłaszaj","dev.con.1.h":"Zmiany w kodzie","dev.con.1.p":"<a class=\"ext\" href=\"https://github.com/dabitlex/YSKAR/blob/main/CONTRIBUTING.md\" target=\"_blank\" rel=\"noopener\">CONTRIBUTING.md</a> mówi, które sprawdzenia muszą przejść przed pushem: sprawdzanie typów i pełny zestaw testów.","dev.con.2.h":"Pomysły i propozycje","dev.con.2.p":"Propozycje dotyczące protokołu i oprogramowania są omawiane otwarcie w <a class=\"ext\" href=\"https://lab.yskar.app\" target=\"_blank\" rel=\"noopener\">YSKAR Lab</a>. Logujesz się portfelem.","dev.con.3.h":"Problemy z bezpieczeństwem","dev.con.3.p":"Zgłaszaj je jako issue na <a class=\"ext\" href=\"https://github.com/dabitlex/YSKAR/issues\" target=\"_blank\" rel=\"noopener\">github.com/dabitlex/YSKAR/issues</a>. Zgłoszenia są publiczne: opisz, co widzisz i jak to odtworzyć, i nigdy nie publikuj swoich 12 słów, PIN-u, pliku portfela ani klucza.","ysr.now.blocks":"bloków","ysr.bar.circ":"W obiegu","ysr.bar.burned":"Spalone","ysr.bar.open":"Jeszcze niewyemitowane","ysr.bar.cap":"Udziały w 21 000 000 YSR, które kiedykolwiek mogą istnieć.","ysr.sched.title":"Emisja według wysokości bloku","ysr.sched.series":"wyemitowano","ysr.sched.when.past":"już wykopany","ysr.sched.when.future":"około {date}, przy 600 s na blok","ysr.t.all":"Pokaż wszystkie 37 er","ysr.t.less":"Pokaż pierwszych 8 er","ysr.t.now":"teraz","ysr.fees.h":"Opłaty","ysr.fees.p":"Przelew płaci opłatę minerom bloku, w którym się znajdzie. Zasady określają tylko dolną granicę. Powyżej niej cena zależy od popytu na miejsce w bloku.","ysr.fees.f1":"Dolna granica według konsensusu","ysr.fees.f1.v":"1 jednostka za bajt","ysr.fees.f2":"Dolna granica do przekazania dalej","ysr.fees.f2.v":"10 jednostek za bajt. To ustawienie węzłów, a nie reguła konsensusu.","ysr.fees.f3":"Zwykły przelew o rozmiarze 168 bajtów","ysr.fees.f3.v":"co najmniej, w tej chwili","ysr.fees.f4":"Wolna, normalna, szybka","ysr.fees.f4.v":"Te trzy poziomy różnią się dopiero wtedy, gdy bloki są pełne. W przeciwnym razie opłata minimalna wystarczy na następny blok.","ysr.fees.f5":"Najmniejsza kwota","ysr.fees.f5.v":"100 jednostek, czyli 0,000001 YSR","ysr.fees.f6":"Przelewy czekające na blok","ysr.noprice.h":"Bez ceny, bez obietnic","ysr.noprice.p1":"YSR nie ma ceny ani rynku i nie jest notowany na żadnej giełdzie. Nic na tej stronie nie obiecuje, że to się zmieni, i nikt nie powinien kopać z takim oczekiwaniem.","ysr.noprice.p2":"YSR ma za to zestaw zasad, które każdy może sprawdzić: stałe maksimum, publiczny harmonogram emisji i monety, które może ruszyć tylko klucz ich właściciela.","tech.header.h":"Blok zaczyna się od 136 bajtów","tech.header.p1":"Nagłówek wskazuje poprzedni blok, zobowiązuje się do każdej transakcji i każdego salda po bloku oraz zawiera nonce znaleziony przez minera. Hash bloku to SHA-256, zastosowany dwukrotnie, dokładnie na tych bajtach.","tech.header.p2":"Długość jest wybrana celowo. SHA-256 pracuje na blokach po 64 bajty, a wszystko poza nonce mieści się w pierwszych 128. Miner oblicza tę część raz na zadanie; każda kolejna próba kosztuje dwa kroki kompresji.","tech.pow.h":"Praca, którą każdy może sprawdzić","tech.pow.p1":"Blok jest ważny tylko wtedy, gdy jego hash, odczytany jako liczba, nie jest większy od celu. Cel wynika z trudności. Nie ma drogi na skróty: jedynym sposobem na znalezienie takiego hasha jest próbowanie kolejnych nonce, a sprawdzenie wyniku wymaga dwóch obliczeń hasha.","tech.pow.p2":"Jedna jednostka trudności oznacza 65 536 oczekiwanych prób. Przy obecnej trudności <span class='mono' data-live='difficulty'></span> sieć potrzebuje około <span data-live='attempts'></span> prób na jeden blok.","tech.diff.h":"Trudność podąża za siecią","tech.diff.p1":"Trudność jest przeliczana dla każdego bloku na podstawie ostatnich 45 bloków. Nowsze bloki liczą się bardziej niż starsze, więc łańcuch szybko reaguje, gdy mocy obliczeniowej przybywa lub ubywa.","tech.diff.p2":"Każdy węzeł wylicza ten sam zakres z tych samych bloków i odrzuca blok, który podaje trudność spoza niego. Używane są wyłącznie liczby całkowite, więc dwa węzły nigdy nie zaokrąglą inaczej.","tech.diff.chart":"Trudność od bloku 1","tech.diff.cap":"Średnia z każdych 24 bloków do bloku <span data-live='snapTip'></span>. Skala jest logarytmiczna: każda linia to dziesięć razy więcej niż ta poniżej.","tech.diff.f1":"Okno","tech.diff.f1.v":"ostatnie 45 bloków, najnowsze z największą wagą","tech.diff.f2":"Największy krok","tech.diff.f2.v":"czterokrotnie w górę lub w dół na blok","tech.diff.f3":"Liczony czas rozwiązania","tech.diff.f3.v":"od 1 do 3600 sekund na blok","tech.diff.f4":"Reguła awaryjna","tech.diff.f4.v":"po 1800 sekundach bez bloku wymaganie spada proporcjonalnie do czasu oczekiwania","tech.diff.f5":"Znaczniki czasu","tech.diff.f5.v":"późniejsze niż mediana ostatnich 11 bloków, najwyżej 120 sekund przed zegarem węzła","tech.acc.h":"Konta i przelewy","tech.acc.p1":"YSKAR przechowuje jedno saldo i jeden nonce na adres. Przelew podaje nadawcę, odbiorcę, kwotę i opłatę oraz jest podpisany kluczem nadawcy. Bez tego klucza nikt nie może ruszyć monet.","tech.acc.p2":"Korzeń stanu w każdym nagłówku zobowiązuje się do wszystkich sald. Węzeł, który odtwarza łańcuch od bloku 0, dochodzi do tych samych sald co każdy inny węzeł albo odrzuca blok.","tech.tx.title":"Przelew, 168 bajtów","tech.tx.p":"Plus opcjonalna notatka do 32 bajtów. Rozmiary w bajtach.","tech.tx.aria":"Pola przelewu i ich rozmiary w bajtach","tech.tx.f1":"Wersja i typ","tech.tx.f2":"Adres nadawcy","tech.tx.f3":"Adres odbiorcy","tech.tx.f4":"Kwota","tech.tx.f5":"Opłata","tech.tx.f6":"Nonce nadawcy","tech.tx.f7":"Wysokość wygaśnięcia i długość notatki","tech.tx.f8":"Klucz publiczny","tech.tx.f9":"Podpis","tech.acc.f1":"Ważny tylko raz","tech.acc.f1.v":"Nonce musi być równy liczbie przelewów wykonanych dotąd przez nadawcę, więc tego samego przelewu nigdy nie da się zastosować dwa razy.","tech.acc.f2":"Związany z tą siecią","tech.acc.f2.v":"Podpis obejmuje chain ID. Przelew podpisany dla YSKAR jest nieważny gdziekolwiek indziej.","tech.acc.f3":"Wygaśnięcie","tech.acc.f3.v":"Nadawca może podać ostatnią wysokość bloku. Po niej przelew nigdy już nie trafi do bloku.","tech.acc.f4":"Notatka","tech.acc.f4.v":"Do 32 bajtów, zapisanych publicznie w łańcuchu.","tech.acc.f5":"Opłata minimalna","tech.acc.f5.v":"1 jednostka za bajt według konsensusu. Węzły przekazują dalej od 10 jednostek za bajt. Opłaty trafiają do minerów bloku.","tech.acc.f6":"Zwykły przelew kosztuje","tech.acc.f6.v":"w tej chwili co najmniej","tech.key.aria":"Od 12 słów do adresu","tech.key.1":"Słowa seed","tech.key.2":"Ścieżka wyprowadzania klucza","tech.key.3":"Para kluczy","tech.key.4":"Adres","tech.key.p":"Portfel to 12 albo 24 słowa (BIP39). Klucz jest z nich wyprowadzany na urządzeniu (SLIP-0010), a adres to pierwsze 20 bajtów hasha SHA-256 klucza publicznego, zapisane w bech32m. Słowa nigdy nie opuszczają urządzenia, które je utworzyło.","tech.nodes.h":"Każdy węzeł sprawdza każdy blok","tech.nodes.p1":"Pełny węzeł przechowuje cały łańcuch i przyjmuje blok dopiero po jego całkowitym sprawdzeniu, niezależnie od tego, czy blok pochodzi od innego węzła, czy od własnego minera. Sprawdzenia przebiegają w tej kolejności.","tech.nodes.link":"Uruchom pełny węzeł","tech.check.1":"Wersja, najwyżej 2000 transakcji, dokładnie jedna transakcja z nagrodą na pierwszym miejscu oraz korzeń transakcji.","tech.check.2":"Hash nagłówka, zastosowany dwukrotnie, nie jest większy od celu wynikającego z podanej trudności.","tech.check.3":"Wysokość to wysokość bloku nadrzędnego plus jeden, a poprzedni hash to hash bloku nadrzędnego.","tech.check.4":"Późniejszy niż mediana ostatnich 11 bloków, nie wcześniejszy niż blok nadrzędny i najwyżej 120 sekund przed zegarem węzła.","tech.check.5":"Podana trudność mieści się w zakresie wynikającym z poprzednich bloków.","tech.check.6":"Podpis, nadawca, nonce, saldo, opłata i wygaśnięcie każdego przelewu. Transakcja z nagrodą wypłaca dokładnie nagrodę za blok plus opłaty.","tech.check.7":"Korzeń obliczony ze wszystkich kont po bloku jest równy korzeniowi stanu w nagłówku.","tech.nodes.chain.h":"Który łańcuch się liczy","tech.nodes.chain.p":"Ważny łańcuch o największej skumulowanej pracy, przy czym pracą bloku jest jego trudność. Węzeł przechowuje konkurencyjne bloki i przełącza się, gdy inna gałąź ma więcej pracy.","tech.nodes.pool.h":"Poole bez powierzania środków","tech.nodes.pool.p":"Transakcja z nagrodą w bloku może wypłacić środki nawet 64 adresom. Rozliczenie poola staje się tą transakcją, więc łańcuch płaci każdemu minerowi bezpośrednio, a operator nigdy nie trzyma cudzych monet. <a href='/mining#pools'>Jak działają poole</a>","tech.rev.h":"Zasady zmieniają się na określonej wysokości bloku","tech.rev.p":"Zmiana zasad jest zapisana w kodzie razem z wysokością, od której obowiązuje. Wszystkie węzły przełączają się na tym samym bloku, a każdy blok poniżej tej wysokości zachowuje swoje zasady, bajt po bajcie.","tech.rev.c1":"Wersja","tech.rev.c2":"Od bloku","tech.rev.c3":"Zmiana","tech.rev.c4":"Status","tech.rev.2":"Transakcja z nagrodą może wypłacać środki kilku adresom. Na tym opierają się poole.","tech.rev.3":"Minimalna opłata za bajt zastępuje opłatę stałą i obowiązuje najmniejsza kwota.","tech.rev.4":"Pole trudności może przechowywać wartości dowolnej wielkości.","tech.rev.5":"Surowsze zasady dla znaczników czasu, kodowania bloków i transakcji z nagrodą.","tech.rev.6":"Konta wspólne, blokady czasowe i hashowe, płatności zbiorcze, nowe drzewo stanu i wyższe limity.","tech.rev.note":"Wersje od 2 do 5 poprawiały i zaostrzały zasady. Wersja 6 jest pierwszą, która dodaje nowe możliwości, i pierwszą, za którą starsze węzły nie mogą podążać.","tech.v6.h":"Wersja 6","tech.v6.p":"Następna zmiana zasad zaczyna się w bloku 10 000. Społeczność wybrała tę wysokość w głosowaniu 25 października 2026 r. Zmienia ona zapis konta, format adresu i format transakcji, żeby konta mogły więcej niż tylko przechowywać saldo.","tech.v6.count":"Blok 10 000","tech.v6.spec":"Przeczytaj specyfikację wersji 6","tech.v6.1.h":"Konta wspólne","tech.v6.1.p":"Konta, z których wydanie środków wymaga kilku podpisów, na przykład 2 z 3, z maksymalnie 16 kluczami. Dla wspólnych środków i bezpieczniejszego oszczędzania.","tech.v6.2.h":"Blokady czasowe","tech.v6.2.p":"YSR, które można wydać dopiero od wybranej wysokości bloku.","tech.v6.3.h":"Blokady hashowe","tech.v6.3.p":"Płatność zostaje zwolniona tylko w zamian za sekret, a po ustalonej wysokości wraca do nadawcy. Dwie strony mogą handlować bez wzajemnego zaufania.","tech.v6.4.h":"Płatności zbiorcze","tech.v6.4.p":"Jedna transakcja płaci naraz nawet 1000 odbiorcom.","tech.v6.5.h":"Więcej miejsca w bloku","tech.v6.5.p":"Do 5000 transakcji na blok zamiast 2000, a blok poola może wypłacić środki nawet 255 adresom zamiast 64.","tech.v6.6.h":"Fundament na przyszłość","tech.v6.6.p":"Drzewo stanu zbudowane z myślą o wielu tysiącach kont, adresy z wersją oraz identyfikator forka w każdym podpisie.","tech.v6.same.h":"Co się nie zmienia","tech.v6.same.1":"21 milionów YSR i harmonogram halvingów","tech.v6.same.2":"10-minutowe bloki, SHA-256 i zasady trudności","tech.v6.same.3":"Każdy adres, każdy klucz i każde saldo","tech.v6.do.h":"Co musisz zrobić","tech.v6.do.1":"Zaktualizuj portfel i węzeł przed blokiem 10 000","tech.v6.do.2":"Minery, minery GPU i pakiet HiveOS nie wymagają aktualizacji","tech.v6.do.3":"Nieaktualny portfel nadal odbiera YSR. Nie może wysyłać, dopóki nie zostanie zaktualizowany","tech.lim.h":"Znane ograniczenia","tech.lim.p":"Przed czym system dziś nie chroni. Lista pochodzi z własnego dokumentu bezpieczeństwa projektu.","tech.lim.link":"Pełny model bezpieczeństwa","tech.lim.1.h":"Mała sieć","tech.lim.1.p":"Sieć ma dwa węzły seed, oba prowadzone przez tego samego operatora. Proof of Work chroni łańcuch tylko dopóty, dopóki żadna pojedyncza strona nie kontroluje większości mocy obliczeniowej, a mocą obliczeniową, która kopie przez jeden pool, kieruje operator tego poola.","tech.lim.2.h":"Brak checkpointów","tech.lim.2.p":"Węzeł przełącza się na każdy ważny łańcuch o większej pracy, niezależnie od tego, jak daleko wstecz się rozgałęzia. Traktuj przelew jako tym bardziej ostateczny, im więcej bloków zbudowano nad nim.","tech.lim.3.h":"Źródło danych explorera","tech.lim.3.p":"Explorer i aplikacje czytają z lustra, czyli kopii łańcucha w bazie danych utrzymywanej dla szybkości. To udogodnienie, a nie źródło prawdy: łańcuch to to, co do czego zgadzają się pełne węzły.","tech.lim.4.h":"Miejsca w poolu","tech.lim.4.p":"Pool ma najwyżej 64 miejsca, 63, jeśli pobiera opłatę; od wersji 6 będzie to 255 i 254. Do otwarcia sesji wystarczy ważny adres, więc miejsca można zająć małym kosztem.","tech.lim.5.h":"Otwarte interfejsy","tech.lim.5.p":"Interfejs HTTP węzła nie ogranicza liczby zapytań na klienta. W przypadku węzła publicznego musi to robić reverse proxy.","tech.docs.1":"Specyfikacja protokołu: formaty, hashowanie, trudność, reguły ważności i wektory testowe.","tech.docs.3":"Co wymuszają kryptografia i konsensus, czemu musisz zaufać oraz znane ograniczenia.","miner.title":"Poszukaj nonce samodzielnie","miner.state":"Działa w Twojej przeglądarce","miner.intro":"Twoja przeglądarka bierze nagłówek najnowszego bloku i próbuje kolejnych nonce względem łatwiejszego celu. Prawdziwy cel jest daleko poza zasięgiem przeglądarki.","miner.bits":"Zerowe bity, od których musi zaczynać się hash","miner.odds":"Bity: {b}. Mniej więcej 1 hash na {n}","miner.start":"Rozpocznij szukanie","miner.stop":"Stop","miner.attempts":"Próby","miner.speed":"Tempo","miner.time":"Czas","miner.nonce":"Znaleziony nonce","miner.hash":"Ostatnio sprawdzony hash","miner.hashFound":"Znaleziony hash","miner.target":"Cel tej demonstracji","miner.found":"Znaleziono. Liczba prób: {n}.","miner.none":"Liczba prób: {n}, żaden hash nie znalazł się poniżej celu. Zacznij od nowa albo ustaw mniej zerowych bitów.","miner.stopped":"Zatrzymano. Liczba prób: {n}.","miner.real":"Przy {r} ta przeglądarka szukałaby prawdziwego bloku przy dzisiejszej trudności średnio mniej więcej {t}.","field.version":"Wersja","field.version.d":"Wersja nagłówka. Dziś wynosi 1, a wraz z wersją konsensusu 6 zmieni się na 6.","field.height":"Wysokość","field.height.d":"Numer tego bloku, liczony od bloku 0.","field.prev":"Poprzedni hash","field.prev.d":"Hash poprzedniego bloku. Łączy bloki w łańcuch: zmiana starego bloku zmieniłaby każdy hash po nim.","field.merkle":"Korzeń transakcji","field.merkle.d":"Jeden hash ze wszystkich transakcji w bloku. Zmiana choćby jednego bajtu w którejkolwiek z nich go zmienia.","field.state":"Korzeń stanu","field.state.d":"Jeden hash ze wszystkich sald i nonce po tym bloku. Każdy węzeł sam go oblicza i porównuje.","field.time":"Znacznik czasu","field.time.d":"Kiedy miner zbudował blok. Musi być późniejszy niż mediana ostatnich 11 bloków.","field.diff":"Trudność","field.diff.d":"Jak trudny musiał być ten blok. Cel wynika z niej: 2^240 podzielone przez trudność.","field.count":"Liczba transakcji","field.count.d":"Ile transakcji zawiera blok, łącznie z tą, która wypłaca nagrodę.","field.extra":"Extranonce","field.extra.d":"Wartość, którą węzeł przydziela każdemu minerowi, żeby dwóch minerów nigdy nie przeszukiwało tych samych nagłówków.","field.nonce":"Nonce","field.nonce.d":"Liczba, którą miner zmieniał, aż hash spadł poniżej celu. Między dwiema próbami nie zmienia się nic innego.","proof.fixedBlock":"Utrwalony w łańcuchu","proof.block":"Blok {h}","proof.found":"znaleziony {ago}","proof.fixed":"Bez zmian od 9 wrz 2026","proof.cap":"Nagłówek bloku: 136 bajtów w dziesięciu polach.","proof.bytesLabel":"136 bajtów nagłówka bloku {h}, szesnastkowo","proof.range":"bajty od {a} do {b}","proof.first":"SHA-256 ze 136 bajtów","proof.hash":"SHA-256 zastosowany dwukrotnie: hash bloku","proof.target":"Cel przy trudności {d}","proof.valid":"Poprawny. Hash jest poniżej celu.","proof.invalid":"Niepoprawny. Hash jest powyżej celu.","proof.time":"Obliczono w Twojej przeglądarce w {ms} ms.","proof.again":"Sprawdź ponownie","proof.genesis":"Sprawdź blok 0","proof.latest":"Sprawdź najnowszy blok","proof.open":"Otwórz ten blok w explorerze","check.1":"Struktura","check.2":"Proof of Work","check.3":"Miejsce w łańcuchu","check.4":"Znacznik czasu","check.5":"Trudność","check.6":"Każda transakcja","check.7":"Korzeń stanu","chart.asTable":"Pokaż wartości w tabeli","chart.total":"łącznie","chart.height":"Do bloku","n.2000":"2000","n.4000":"4000","n.6000":"6000","n.7000":"7000","n.10000":"10 000","rev.active":"aktywna od {date}","rev.set":"ustalona, pozostało bloków: {n}","ms.done":"aktywna","home.how.1.h":"Minerzy szukają","home.how.1.p":"Telefony, komputery i karty graficzne raz po raz hashują nagłówek bloku, za każdym razem z innym nonce. Hash poniżej celu sprawia, że blok jest ważny.","home.how.2.h":"Węzły sprawdzają","home.how.2.p":"Każdy pełny węzeł przelicza pracę, podpisy i wszystkie salda, zaczynając od bloku 0. Blok, który łamie jakąś zasadę, zostaje odrzucony, bez względu na to, kto go wysłał.","home.how.3.h":"Blok wypłaca","home.how.3.p":"Nagrodę wypłaca sam blok: tylko znalazcy albo podzieloną między minerów poola, prosto na ich adresy. Pool nigdy nie trzyma cudzych monet.","dev.api.down":"Zapytanie nie powiodło się ({why}). API nie odpowiada stąd w tej chwili."};window.YSKAR_TEXTE_DA&&window.YSKAR_TEXTE_DA("pl");
